INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 1, 'No principio existia o Verbo, e o Verbo estava junto de Deus, e o Verbo era Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 2, 'Estava no princípio junto de Deus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 3, 'Todas as coisas foram feitas por ele; e sem ele nada foi feito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 4, 'Nele estava a vida, e a vida era a luz dos homens,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 5, 'e a luz resplandece nas trevas, e as trevas não o receberam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 6, 'Apareceu um homem enviado por Deus que se chamava João.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 7, 'Veio como testemunha para dar testemunho da luz, a fim de que todos crêssem por meio dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 8, 'Não era a luz, mas veio para dar testemunho da luz,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 9, 'O Verbo era a luz verdadeira, que ilumina todo o homem que vem a este mundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 10, 'Estava no mundo, e o mundo foi feito por ele, e o mundo não o conheceu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 11, 'Veio para o que era seu, e os seus não o receberam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 12, 'Mas a todos os que o receberam, deu poder de se tornarem filhos de Deus, àqueles que crêem no seu nome;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 13, 'os quais não nasceram do sangue, nem da vontade da carne, nem da vontade do homem, mas de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 14, 'E o Verbo se fez carne, e habitou entre nós; e nós vimos a sua glória, glória como de Filho Unigénito do Pai, cheio de graça e de verdade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 15, 'João dá testemunho dele e clama: Este era aquele de quem eu disse: O que há-de vir depois de mim, é mais do que eu, porque existia antes de mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 16, 'Todos nós participamos da sua plenitude, e recebemos graça sobre graça;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 17, 'porque a lei foi dada por Moisés, mas a graça e a verdade foi trazida por Jesus Cristo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 18, 'Ninguém jamais viu Deus; o Filho Unigénito, que está no seio do Pai, ele mesmo é que o deu a conhecer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 19, 'Eis o testemunho de João, quando os Judeus lhe enviaram de Jerusalém sacerdotes e levitas a perguntar-lhe: "Quem és tu"?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 20, 'Ele confessou a verdade, não a negou; e confessou: "Eu não sou o Cristo".'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 21, 'Eles perguntaram-lhe: "Quem és pois? És tu Elias"? Ele respondeu: "Não sou". "És tu o profeta"? Respondeu: "Não".'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 22, 'Disseram-lhe então: "Quem és, pois, para que possamos dar resposta aos que nos enviaram? Que dizes de ti mesmo?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 23, 'Disse-lhes então: Eu sou a voz do que clama no deserto: Endireitai o caminho do Senhor, como disse o profeta Isaías (Is. 40, 3)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 24, 'Ora os que tinham sido enviados eram fariseus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 25, 'Interrogaram-no, dizendo: "Como baptizas, pois, se não és o Cristo, nem Elias, nem o profeta?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 26, 'João respondeu-lhes: "Eu baptizo em água, mas no meio de vós está quem vós não conheceis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 27, 'Esse é o que há-de vir depois de mim, ao qual eu não sou digno de desatar a correia das sandálias."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 28, 'Estas coisas passaram-se em Betânia, da banda de além do Jordão, onde João estava baptizando.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 29, 'No dia seguinte João viu Jesus, que vinha ter com ele, e disse: "Eis o Cordeiro de Deus, eis o que tira o pecado do mundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 30, 'Este é aquele, de quem eu disse: Depois de mim vem um homem que é superior a mim, porque era antes de mim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 31, 'e eu não o conhecia, mas vim baptizar em água, para ele ser reconhecido em Israel."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 32, 'João deu este testemunho: "Vi o Espírito descer do céu em forma de pomba, e repousou sobre ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 33, 'Eu não o conhecia, mas o que me mandou baptizar em água, disse-me: Aquele, sobre quem vires descer e repousar o Espírito, esse é o que baptiza no Espírito Santo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 34, 'Eu o vi, e dei testemunho de que ele é o Filho de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 35, 'Ao outro dia João lá estava novamente com dois de seus discípulos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 36, 'Vendo Jesus que ia passando, disse: "Eis o Cordeiro de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 37, 'Ouvindo as suas palavras, os dois discípulos seguiram Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 38, 'Jesus, voltando-se para trás, e vendo que o seguiam, disse-lhes: "Que buscais vós?" Eles disseram-lhe: "Rabi (que quer dizer Mestre), onde habitas?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 39, 'Jesus disse-lhes: "Vinde ver." Foram, viram onde habitava, e ficaram com ele aquele dia. Era então quase a hora décima.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 40, 'André, irmão de Simão Pedro, era um dos dois que tinham ouvido o que João dissera, e que tinham seguido Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 41, 'Este encontrou primeiro seu irmão Simão, e disse-lhe: "Encontramos o Messias" (que quer dizer Cristo).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 42, 'Levou-o a Jesus. Jesus, fixando nele o olhar, disse: "Tu és Simão, filho de João, tu serás chamado Cefas, que quer dizer Pedro ou Pedra."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 43, 'No dia seguinte Jesus resolveu ir à Galileia. Encontrou Filipe, e disse-lhe: "Segue-me."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 44, 'Filipe era natural da cidade de Betsaida, pátria de André e de Pedro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 45, 'Filipe encontrou Natanael, e disse-lhe: "Encontramos aquele de quem escreveram Moisés na lei e os profetas: Jesus de Nazaré, filho de José."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 46, 'Natanael disse-lhe: "De Nazaré pode porventura sair coisa que seja boa?" Filipe disse-lhe: "Vem ver."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 47, 'Jesus viu Natanael, que ia ter com ele, e disse dele: "Eis um verdadeiro Israelita, em quem não há dolo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 48, 'Natanael disse-lhe: "Donde me conheces tu?" Jesus respondeu-lhe: "Antes que Filipe te chamasse, te vi eu, quando estavas debaixo da figueira."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 49, 'Natanael respondeu: "Mestre, tu és o filho de Deus, tu és o rei de Israel."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 50, 'Jesus respondeu-lhe: "Porque eu te disse que te vi debaixo da figueira, crês; verás coisas maiores que esta."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 51, 'E acrescentou: "Em verdade, em verdade vos digo, vereis o céu aberto, e os anjos de Deus subindo e descendo sobre o Filho do homem."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 1, 'Três dias depois, celebraram-se umas bodas em Caná da Galileia, e encontrava-se lá a Mãe de Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 2, 'Foi também convidado Jesus com seus discípulos para as bodas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 3, 'Faltando o vinho, a Mãe de Jesus disse-lhe; "Não têm vinho."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 4, 'Jesus respondeu-lhe: "Mulher, que nos importa a mim e a ti isso? Ainda não chegou a minha hora."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 5, 'Disse sua Mãe aos que serviam: "Fazei tudo o que ele vos disser."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 6, 'Ora estavam ali seis talhas de pedra, preparadas para a purificação judaica, que levavam cada uma duas a três metretas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 7, 'Jesus disse-lhes: Enchei as talhas de água. Encheram-nas até cima.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 8, 'Então Jesus disse-lhes : "Tirai agora, e levai ao arquitriclino." Eles levaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 9, 'O arquitriclino, logo que provou a água convertida em vinho (ele não sabia donde viera, ainda que o sabiam os serventes, porque tinham tirado a água), o arquitriclino chamou o esposo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 10, 'e disse-lhe: "Todo o homem põe primeiro o bom vinho, e, quando já os convidados têm bebido bem, então lhes apresenta o inferior; tu, ao contrário, tiveste o bom vinho guardado até agora."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 11, 'Tal foi o primeiro milagre de Jesus; fê-lo em Caná da Galileia. Assim manifestou a sua glória, e os seus discípulos creram nele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 12, 'Depois disto, desceu para Cafarnaum, com sua Mãe, seus irmãos e seus discípulos; mas não se demoraram lá muitos dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 13, 'Estava próxima a Páscoa dos Judeus, e Jesus subiu a Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 14, 'Encontrou no templo vendedores de bois, ovelhas e pombas, e os cambistas sentados às suas mesas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 15, 'Tendo feito um azorrague de cordas, expulsou-os a todos do templo, e com eles as ovelhas e os bois, deitou por terra o dinheiro dos cambistas e derribou as suas mesas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 16, 'Aos que vendiam pombas, disse: "Tirai daqui isto, não façais da casa de meu Pai casa de negócio."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 17, 'Então lembraram-se seus discípulos do que está escrito: O zelo da tua casa devorou-me (Ps. 68, 10).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 18, 'Tomaram então a palavra os Judeus, e disseram-lhe: "Com que sinal nos mostras tu que tens autoridade para fazer estas coisas?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 19, 'Jesus respondeu-lhes: "Destruí este templo, e o reedificarei em três dias."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 20, 'Replicaram os Judeus: "Este templo foi edificado em quarenta e seis anos, e tu o reedificarás em três dias?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 21, 'Ora ele falava do templo de seu corpo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 22, 'Quando, pois, ressuscitou dos mortos lembraram-se seus discípulos do que ele dissera, e creram na Escritura e nas palavras que Jesus tinha dito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 23, 'Estando em Jerusalém pela festa da Páscoa, muitos creram no seu nome, vendo os milagres que fazia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 24, 'Mas Jesus não se fiava neles, porque os conhecia a todos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 25, 'e não necessitava de que lhe dessem testemunho de homem algum, pois sabia por si mesmo o que há em cada homem.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 1, 'Havia um homem da seita dos fariseus, chamado Nicodemos; um dos principais entre os Judeus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 2, 'Este foi ter com Jesus, de noite, e disse-lhe: "Mestre, sabemos que foste enviado por Deus como mestre, porque ninguém pode fazer estes milagres que tu fazes, se Deus não estiver com ele."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 3, 'Jesus respondeu-lhe: "Em verdade, em verdade te digo que não pode ver o reino de Deus, senão aquele que nascer de novo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 4, 'Nicodemos disse-lhe: "Como pode um homem nascer, sendo velho? Porventura pode tornar a entrar no ventre de sua mãe e renascer?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 5, 'Jesus respondeu-lhe: "Em verdade, em verdade te digo que quem não renascer da água e do Espirito Santo, não pode entrar no reino de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 6, 'O que nasceu da carne, é carne, o que nasceu do Espírito, é espírito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 7, 'Não te maravilhes de eu te dizer: É preciso que vós nasçais de novo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 8, 'O vento sopra onde quer, e tu ouves a sua voz, mas não sabes donde ele vem, nem para onde vai, assim é todo aquele que nasceu do Espírito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 9, 'Nicodemos disse-lhe: "Com se pode isto fazer?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 10, 'Jesus respondeu: "Tu és mestre em Israel, e não sabes estas coisas?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 11, 'Em verdade, em verdade te digo que nós dizemos o que sabemos, e damos testemunho do que vimos, mas vós não recebeis o nosso testemunho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 12, 'Se, quando vos falo das coisas terrenas, não me acreditais, como me acreditareis, se vos falar das celestes?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 13, 'Ninguém subiu ao céu, senão aquele que desceu do céu, o Filho do homem, que está no céu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 14, 'E como Moisés levantou no deserto a serpente, assim também importa que seja levantado o Filho do homem,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 15, 'a fim de que todo o que crê nele tenha a vida eterna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 16, 'Porque Deus amou de tal modo o mundo, que lhe deu seu Filho unigênito, para que todo o que crê nele não pereça, mas tenha a vida eterna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 17, 'Porque Deus não enviou seu Filho ao mundo, para condenar o mundo, mas para que o mundo seja salvo por ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 18, 'Quem nele crê, não é condenado, mas quem não crê, já está condenado, porque não crê no nome do Filho unigênito de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 19, 'A condenação está nisto: A luz veio ao mundo, e os homens amaram mais as trevas do que a luz, porque as suas obras eram más.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 20, 'Porque todo aquele que faz o mal, aborrece a luz, e não se chega para a luz, a fim de que não sejam reprovadas as as suas obras;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 21, 'mas aquele que procede segundo a verdade, chega-se para a luz, a fim de que seja manifesto que as suas obras são feitas segundo Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 22, 'Depois disto, foi Jesus com seus discípulos para a terra da Judeia. Habitava com eles, e baptizava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 23, 'João estava também baptizando em Enon, junto a Salím, porque havia ali muita água, e o povo concorria para ser baptizado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 24, 'João ainda não tinha sido posto na prisão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 25, 'Levantou-se uma questão entre os discípulos de João e um judeu acerca da purificação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 26, 'Foram ter com João, e disseram-lhe: "Mestre, o que estava contigo da banda de além do Jordão, de quem tu deste testemunho ei-lo que está baptizando, e todos vão a ele."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 27, 'João respondeu: O homem não pode receber coisa alguma, se lhe não for dada do céu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 28, 'Vós mesmo me sois testemunhas de que vos disse: Eu não sou o Cristo, mas fui enviado diante dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 29, 'O que tem a esposa é o esposo, mas o amigo do esposo, que está de pé e o ouve, enche-se de gozo com a voz do esposo. Esta é a minha alegria, e ela é perfeita.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 30, 'Convém que ela cresça e eu diminua.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 31, 'O que vem lá de cima, é superior a todos. O que vem da terra, é da terra, e terrestre é a sua linguagem. O que vem do céu, é superior a todos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 32, 'Ele testifica o que viu e ouviu, mas (quase) ninguém recebe o seu testemunho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 33, 'O que recebe o seu testemunho, certifica que Deus é verdadeiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 34, 'Aquele a quem Deus enviou, fala palavras de Deus, porque Deus não lhe dá o Espírito por medida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 35, 'O Pai ama o Filho, e pôs todas as coisas na sua mão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 36, 'O que crê no Filho,a vida eterna; o que, porém, não crê no Filho, não verá a vida, mas sobre ele pesa a ira de Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 1, 'Quando Jesus soube que os fariseus tinham ouvido que ele fazia mais discípulos e baptizava mais que João,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 2, '(todavia não era o próprio Jesus que baptizava, mas os seus discípulos),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 3, 'deixou a Judeia, e foi outra vez para a Galileia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 4, 'Devia, por isso, passar pela Samaria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 5, 'Chegou, pois, a uma cidade da Samaria chamada Sicar, junto da herdade que Jacó deu a seu filho José.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 6, 'Estava lá o poço de Jacó. Fatigado da viagem, Jesus sentou-se sobre a borda do poço. Era quase a hora sexta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 7, 'Veio uma mulher da Samaria tirar água. Jesus disse-lhe: "Dá-me de beber."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 8, 'Os seus discípulos tinham ido à cidade comprar mantimentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 9, 'Disse-lhe, porém, a mulher Samaritana: "Como, sendo tu judeu, me pedes de beber a mim, que sou samaritana?" Com efeito os Judeus não comunicam com os Samaritanos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 10, 'Jesus respondeu: "Se tu conheceras o dom de Deus, e quem é que te diz: Dá-me de beber, certamente lhe pedirias, e ele te daria de uma água viva."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 11, 'A mulher disse-lhe; "Senhor, tu não tens com que a tirar, e o poço é fundo; donde tens, pois, essa água viva?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 12, 'És tu, porventura, maior do que o nosso pai Jacó, que nos deu este poço, do qual ele mesmo bebeu, e os seus filhos e os seus gados?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 13, 'Jesus respondeu: "Todo aquele que bebe desta água tornará a ter sede,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 14, 'mas o que beber da água que eu lhe der, jamais terá sede: a água que eu lhe der, virá a ser nele uma fonte de água que salte para a vida eterna."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 15, 'A mulher disse-lhe: "Senhor, dá-me dessa água, pára eu não ter mais sede, nem vir aqui tirá-la."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 16, 'Jesus disse-lhe: "Vai, chama teu marido e vem cá."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 17, 'A mulher respondeu: "Não tenho marido." Jesus replicou: "Disseste bem: não tenho marido;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 18, 'porque tiveste cinco maridos, e o que agora tens, não é teu marido; isto disseste com verdade."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 19, 'A mulher disse-lhe: "Senhor, vejo que és profeta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 20, 'Nossos pais adoraram sobre esta montanha, e vós dizeis que em Jerusalém é o lugar onde se deve adorar."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 21, 'Jesus disse-lhe: "Mulher, crê-me que é chegada a hora, em que não adorareis o Pai, nem nesta montanha, nem em Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 22, 'Vós adorais o que não conheceis, nós adoramos o que conhecemos, porque dos Judeus é que vem a salvação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 23, 'Mas vem a hora, e já chegou, em que os verdadeiros adoradores adorarão o Pai em espírito e verdade, porque é destes adoradores que o Pai deseja.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 24, 'Deus é espírito, e em espírito e verdade é que o devem adorar os que o adoram."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 25, 'A mulher disse-lhe: "Eu sei que deve vir o Messias que se chama Cristo; quando, pois, ele vier, nos anunciará todas as coisas."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 26, 'Jesus disse-lhe: "Sou eu, que falo contigo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 27, 'Nisto chegaram seus discípulos, e maravilharam-se de que estivesse falando com uma mulher. Nenhum contudo lhe disse: "Que é o que perguntas?" ou: "Por que falas com ela?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 28, 'A mulher, então, deixou o seu cântaro, foi à cidade e disse àquela gente:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 29, '"Vinde ver um homem, que me disse tudo o que eu tenho feito; será este porventura o Cristo?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 30, 'Saíram da cidade e foram ter com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 31, 'Entretanto seus discípulos instavam com ele, dizendo: "Mestre, come."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 32, 'Mas ele respondeu-lhes: "Eu tenho um alimento para comer, que vós não sabeis."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 33, 'Pelo que diziam os discípulos uns para os outros: "Será caso que alguém lhe trouxesse de comer?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 34, 'Jesus disse-lhes: "A minha comida é fazer a vontade daquele que me enviou e cumprir a sua obra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 35, 'Não dizeis vós que ainda há quatro meses até à ceifa? Mas eu digo-vos: Levantai os olhos e vede os campos que já estão branquejando para a ceifa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 36, 'O que sega recebe recompensa e junta o fruto para a vida eterna, para que assim o que semeia, como o que sega, juntamente se regozijem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 37, 'Porque nisto se verifica o ditado: Um é o que semeia, e outro o que sega.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 38, 'Eu enviei-vos a segar o que vós não trabalhaste; outros trabalharam, e vós recolheis o fruto dos seus trabalhos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 39, 'Muitos Samaritanos daquela cidade creram em Jesus, por causa da palavra daquela mulher, que dava este testemunho: "Ele disse-me tudo o que tenho feito."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 40, 'Vindo, pois, ter com ele os Samaritanos, pediram-lhe que ficasse com eles. Ficou lá dois dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 41, 'Muitos mais creram nele em virtude da sua palavra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 42, 'E diziam à mulher: "Não é já pela tua palavra que cremos nele, mas é porque nós próprios o ouvimos, e sabemos que ele é verdadeiramente o Salvador do mundo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 43, 'Passados dois dias, partiu Jesus dali para a Galileia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 44, 'Porque o mesmo Jesus tinha afirmado que um profeta não tem respeito na sua pátria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 45, 'Tendo chegado à Galileia, receberam-no bem os Galileus, porque tinham visto todas as coisas que ele havia feito em Jerusalém no dia da festa; pois também tinham ido à festa'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 46, 'Foi, pois, novamente a Caná da Galileia, onde tinha convertido a água em vinho. Havia em Cafarnaum um funcionário real, cujo filho estava doente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 47, 'Este, tendo ouvido dizer que Jesus chegara da Judeia à Galileia, foi ter com ele e rogou-lhe que fosse a sua casa curar seu filho, que estava a morrer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 48, 'Jesus disse-lhe: "Vós, se não virdes milagres e prodígios, não credes."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 49, 'O funcionário real disse-lhe: "Senhor, vem antes que meu filho morra"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 50, 'Jesus disse-lhe: "Vai, o teu filho vive." Deu o homem crédito ao que Jesus lhe disse, e partiu'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 51, 'Quando já ia para casa, vieram os criados ao seu encontro, e deram-lhe a nova de que seu filho vivia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 52, 'Perguntou-lhes a hora em que o doente se achara melhor. Disseram-lhe: "Ontem, à hora sétima, o deixou a febre."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 53, 'Reconheceu então o pai ser aquela mesma a hora em que Jesus lhe dissera: "Teu filho vive". Acreditou ele, assim como toda a sua família.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 54, 'Foi este o segundo milagre que Jesus fez, depois de ter vindo da Judeia para a Galileia.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 1, 'Depois disto, houve uma festa dos Judeus e Jesus subiu a Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 2, 'Ora há em Jerusalém, junto da porta das Ovelhas, uma piscina, que em hebreu se chama Bezatha, a qual tem cinco pórticos'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 3, 'Nestes jazia uma multidão de enfermos, cegos, coxos, paralíticos, os quais esperavam o movimento da água.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 4, 'Porque um anjo do Senhor descia de tempos a tempos à piscina, e agitava a água. O primeiro que descesse à piscina, depois do movimento da água, ficava curado de qualquer doença que tivesse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 5, 'Estava ali um homem que, há trinta e oito anos, se encontrava enfermo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 6, 'Jesus, vendo-o deitado e sabendo que estava assim há muito, disse-lhe: "Queres ficar são?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 7, 'O enfermo respondeu- lhe: "Senhor, não tenho uma pessoa que me lance na piscina, quando a água é agitada; enquanto eu vou, outro desce primeiro do que eu."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 8, 'Jesus disse-lhe: "Levanta-te, toma o teu leito e anda."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 9, 'No mesmo instante, ficou são aquele homem, tomou o seu leito e começou a andar. Ora aquele dia era um sábado,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 10, 'Por isso os Judeus diziam ao que tinha sido curado: "Hoje é sábado, não te é licito levar o teu leito."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 11, 'Ele respondeu-lhes: "Aquele que me curou, disse-me: Toma o teu leito, e anda."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 12, 'Perguntaram- lhe então: "Quem é esse homem que te disse: Toma o teu leito e anda?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 13, 'Porém o que tinha sido curado não sabia quem ele era, porque Jesus havia desaparecido sem ser notado, graças à multidão que estava naquele lugar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 14, 'Depois disto, Jesus encontrou-o no templo e disse-lhe: "Eis que estás são; não peques mais, para que te não suceda coisa pior."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 15, 'Foi aquele homem anunciar aos Judeus que era Jesus quem o tinha curado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 16, 'Por isto os Judeus perseguiam Jesus, porque fazia estas coisas ao sábado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 17, 'Mas Jesus respondeu-lhes: "Meu Pai não cessa de operar, e eu opero também."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 18, 'Por isso, os Judeus procuravam com maior ardor matá-lo, porque não somente violava o sábado, mas também dizia que Deus era seu Pai, fazendo-se igual a Deus, Jesus respondeu, pois, e disse-lhes:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 19, 'Em verdade, em verdade vos digo: O Filho não pode de si mesmo fazer coisa alguma, mas somente o que vir fazer ao Pai; porque tudo o que fizer o Pai, o faz igualmente o Filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 20, 'Porque o Pai ama o Filho, e mostra-lhe tudo o que faz; e lhe mostrará maiores obras do que estas, até ao ponto de vós ficardes admirados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 21, 'Porque assim como o Pai ressuscita os mortos e lhes dá vida, assim também o Filho dá vida àqueles que quer'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 22, 'O Pai a ninguém julga, mas deu ao Filho todo o poder de julgar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 23, 'afim de que todos honrem o Filho como honram o Pai. O que não honra o Filho, não honra o Pai, que o enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 24, 'Em verdade, em verdade vos digo que quem ouve a minha palavra e crê naquele que me enviou, tem a vida eterna e não incorre na sentença da condenação, mas passou da morte para vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 25, 'Em verdade, em verdade vos digo que vem a hora, e já chegou, em que os mortos ouvirão a voz do Filho de Deus, e os que a ouvirem, viverão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 26, 'Com efeito assim como o Pai tem a vida em si mesmo, assim deu ao Filho ter vida em si mesmo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 27, 'e deu-lhe o poder de julgar, porque é Filho do homem'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 28, 'Não vos admireis disso, porque virá tempo em que todos os que se encontram nos sepulcros ouvirão a sua voz,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 29, 'e os que tiverem feito obras boas sairão para a ressurreição da vida, mas os que tiverem feito obras más, sairão ressuscitados para a condenação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 30, 'Não posso de mim mesmo fazer coisa alguma. Julgo segundo o que ouço (de meu Pai), e o meu juízo é justo, porque não busco a minha vontade, mas a vontade daquele que me enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 31, 'Se dou testemunho de mim mesmo, o meu testemunho não é verdadeiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 32, 'Outro é o que dá testemunho de mim; e sei que é verdadeiro o testemunho que dá de mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 33, 'Vós enviastes (mensageiros) a João, e ele deu testemunho da verdade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 34, 'Eu, porém, não recebo o testemunho do homem, mas digo-vos estas coisas, a fim de que sejais salvos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 35, 'João era uma lâmpada ardente e luminosa. E vós poucos momentos quisestes gozar da sua luz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 36, 'Mas tenho um testemunho maior que o de João: as obras que meu Pai me deu que cumprisse, estas mesmas obras que eu faço, dão testemunho de mim, de que o Pai me enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 37, 'E o Pai que me enviou, esse mesmo deu testemunho de mim. Vós nunca ouvistes a sua voz, nem vistes a sua face,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 38, 'não tendes permanente em vós a sua palavra, porque não credes no que ele enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 39, 'Examinais as Escrituras, visto que julgais ter nelas a vida eterna: elas são as que dão testemunho de mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 40, 'E não quereis vir a mim, para terdes vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 41, 'A glória, não a recebo dos homens,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 42, 'mas sei que não tendes em vós o amor de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 43, 'Vim em nome de meu Pai, e vós não me recebeis; se vier outro em seu próprio nome, recebê-lo-eis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 44, 'Como podeis crer, vós que recebeis a glória uns dos outros, e não buscais a glória que só de Deus vem?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 45, 'Não julgueis que sou eu que vos hei-de acusar diante do Pai; Moisés, em quem vós confiais, é que vos acusará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 46, 'Se crêsseis em Moisés, certamente creríeis também em mim, porque ele escreveu de mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 47, 'Porém, se não dais crédito aos seus escritos, como haveis de dar crédito às minhas palavras?"');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 1, 'Depois disto, passou Jesus à outra banda do mar da Galileia, isto é, de Tiberíades?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 2, 'Seguia-o uma grande multidão, porque via os milagres que fazia em favor dos enfermos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 3, 'Jesus subiu a um monte e sentou-se ali com seus discípulos'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 4, 'Ora a Páscoa, a festa dos Judeus, estava próxima.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 5, 'Jesus, então, tendo levantado os olhos e visto que vinha ter com ele uma grande multidão, disse a Filipe: "Onde compraremos nós pão, para dar de comer a esta gente?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 6, 'Dizia, porém, isto para o experimentar, porque sabia o que havia de fazer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 7, 'Filipe respondeu-lhe: "Duzentos dinheiros de pão não bastam para que cada um receba um pequeno bocado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 8, 'Um de seus discípulos, André, irmão de Simão Pedro, disse-lhe:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 9, '"Está aqui um jovem, que tem cinco pães de cevada e dois peixes, mas que é isto para tanta gente?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 10, 'Jesus, porém, disse: "Mandai sentar essa gente." Havia naquele lugar muita erva. Sentaram-se, pois, os homens, em número de cerca de cinco mil.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 11, 'Tomou, então, Jesus os pães. e, tendo dado graças, distribuiu-os entre os que estavam recostados; e igualmente dos peixes quanto queriam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 12, 'Estando saciados, disse a seus discípulos: "Recolhei os pedaços que sobejaram, para que nada se perca."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 13, 'Eles os recolheram e encheram doze cestos de pedaços dos cinco pães de cevada, que sobejaram aos que tinham comido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 14, 'Vendo então aqueles homens o milagre que Jesus fizera, diziam: "Este é verdadeiramente o profeta que deve vir ao mundo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 15, 'Jesus, sabendo que o viriam arrebatar para o fazerem rei, retirou-se, de novo, ele só para o monte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 16, 'Quando chegou a tarde, seus discípulos desceram para junto do mar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 17, 'e, tendo subido para uma barca, atravessaram o mar em direção a Cafarnaum. Era já escuro, e Jesus ainda não tinha ido ter com eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 18, 'Entretanto o mar começava a empolar-se, por causa do vento forte que soprava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 19, 'Tendo remado cerca de vinte e cinco ou trinta estádios, viram Jesus caminhando sobre o mar, em direção à barca, e ficaram atemorizados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 20, 'Mas ele disse-lhes: "Sou eu, não temais."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 21, 'Quiseram então recebê-lo na barca; e logo a barca chegou à terra, para onde iam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 22, 'No dia seguinte, a multidão, que tinha ficado da outra banda do mar, advertiu que não havia ali mais que uma barca, e que Jesus não tinha entrado nela com seus discípulos, mas que os seus discípulos tinham partido sós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 23, 'Entretanto arribaram de Tiberíades outras barcas, perto do lugar onde haviam comido o pão, depois de o Senhor ter dado graças.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 24, 'Tendo, pois, visto a multidão que não estava lá nem Jesus nem os seus discípulos, entrou naquelas barcas e foi a Cafarnaum, em busca de Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 25, 'Tendo-o encontrado da banda de além do mar, disseram lhe: "Mestre, quando chegaste aqui?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 26, 'Jesus respondeu-lhes: "Em verdade, em verdade, vos digo: Vós buscais-me, não porque vistes os milagres, mas porque comestes dos pães e ficastes saciados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 27, 'Trabalhai não pela comida que perece, mas pela que dura até à vida eterna, a qual o Filho do homem vos dará. Porque nele imprimiu Deus Pai o seu selo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 28, 'Eles, então, disseram-lhe: "Que devemos nós fazer para praticar obras de Deus?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 29, 'Jesus respondeu: "A obra de Deus é esta: Que acrediteis naquele que enviou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 30, 'Mas eles disseram-lhe: "Que milagre fazes tu, para que o vejamos e acreditemos em ti? Que fazes tu?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 31, 'Nossos pais comeram o maná no deserto, segundo está escrito: Deu-lhes a, comer o pão do céu. (Ps. 77, 24)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 32, 'Jesus respondeu-lhes: "Em verdade, em verdade, vos digo: Moisés não vos deu o pão do céu, mas meu Pai é que vos dá o verdadeiro pão do céu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 33, 'Porque o pão de Deus é o que desceu do céu e dá a vida ao mundo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 34, 'Então disseram-lhe: "Senhor, dá-nos sempre desse pão"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 35, 'Jesus respondeu-lhes: "Eu sou o pão da vida; o que vem a mim, não terá jamais fome, e o que crê em mim, não terá jamais sede.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 36, 'Porém já vos disse que vós me vistes e que não credes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 37, 'Tudo o que o Pai me dá, virá a mim; e aquele que vem a mim, não o lançarei fora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 38, 'Porque desci do céu, não para fazer a minha vontade, mas a vontade daquele que me enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 39, 'Ora a vontade daquele que me enviou, é que eu não perca nada do que me deu, mas que o ressuscite no último dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 40, 'A vontade de meu Pai, que me enviou, é que todo o que vê o Filho e crê nele tenha a vida eterna; e eu o ressuscitarei no último dia."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 41, 'Murmuravam, pois, dele os Judeus, porque dissera: "Eu sou o pão que desceu do céu."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 42, 'Diziam: "Por ventura não é este aquele Jesus, filho de José, cujo pai e mãe nós conhecemos? Como, pois, diz ele: Descido céu?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 43, 'Jesus, replicando, disse-lhes: "Não murmureis entre vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 44, 'Ninguém pode vir a mim, se o Pai que me enviou, o não atrair; e eu o ressuscitarei no último dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 45, 'Está escrito nos profetas: E serão todos ensinados por Deus (Is. 54, 13). Portanto todo aquele que ouve e aprende do Pai ; vem a mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 46, 'Não porque alguém tenha visto o Pai, excepto aquele que vem de Deus; esse viu o Pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 47, 'Em verdade, em verdade, vos digo: O que crê em mim, tem a vida eterna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 48, 'Eu sou o pão da vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 49, 'Vossos pais comeram o maná, no deserto, e morreram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 50, 'Este é o pão que desceu do céu, para que aquele que dele comer não morra,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 51, 'Eu sou o pão vivo, descido do céu. Quem comer deste pão, viverá eternamente; e o pão que eu darei, é a minha carne (que será sacrificada) para a salvação do mundo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 52, 'Disputavam, então, entre si os Judeus: "Como pode este dar-nos a comer a sua carne?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 53, 'Jesus disse-lhes: "Em verdade, em verdade, vos digo: Se não comerdes a carne do Filho do homem, e não beberdes o seu sangue, não tereis a vida em vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 54, 'O que come a minha carne e bebe o meu sangue, tem a vida eterna, e eu o ressuscitarei no último dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 55, 'Porque a minha carne é verdadeiramente comida, e o meu sangue verdadeiramente bebida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 56, 'O que come a minha carne e bebe o meu sangue, permanece em mim e eu nele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 57, 'Assim como me enviou o Pai que vive, e eu vivo pelo Pai, assim o que me comer a mim, esse mesmo também viverá por mim'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 58, 'Este é o pão que desceu do céu. Não é como o pão que comeram os vossos pais, que morreram. O que come deste pão viverá eternamente."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 59, 'Jesus disse estas coisas, ensinando em Cafarnaum, na Sinagoga'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 60, 'Muitos de seus discípulos, ouvindo isto, disseram: "Dura é esta linguagem; quem a pode ouvir?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 61, 'Jesus, conhecendo em si mesmo que seus discípulos murmuravam por isto, disse-lhes: "Isto escandaliza- vos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 62, 'Que será quando virdes subir o Filho do homem para onde estava antes?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 63, 'E o espírito que vivifica; a carne para nada aproveita. As palavras que eu vos disse, são espírito e vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 64, 'Mas há alguns de vós que não crêem. Com efeito Jesus sabia desde o princípio quais eram os que não criam, e quem havia de o entregar'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 65, 'Depois acrescentou: "Por isso eu vos disse que ninguém pode vir a mim, se lhe não for concedido por meu Pai."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 66, 'Desde então muitos de seus discípulos tornaram atrás, e já não andavam com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 67, 'Por isso Jesus disse aos doze: "Quereis vós também retirar-vos?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 68, 'Simão Pedro respondeu-lhe: "Senhor, para quem havemos nós de ir? Tu tens palavras de vida eterna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 69, 'E nós acreditamos e conhecemos que tu és o Santo de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 70, 'Jesus replicou: "Não fui eu que vos escolhi, a vós os doze? E contudo um de vós é um demônio."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 71, 'Falava de Judas, filho de Simão Iscariote, porque era este que o havia de entregar, não obstante ser um dos doze.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 1, 'Depois disto, andava Jesus pela Galileia; não queria andar pela Judeia, visto que os Judeus queriam matar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 2, 'Estava próxima a festa dos Judeus, chamada dos Tabernáculos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 3, 'Disseram-lhe, pois, seus irmãos: "Sai daqui e vai para a Judeia, a fim de que também os teus discípulos vejam as obras que fazes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 4, 'Porque ninguém que deseja ser conhecido em público, faz coisa alguma em segredo. Já que fazes estas coisas, manifesta-te ao mundo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 5, 'Nem mesmo os seus irmãos criam nele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 6, 'Ainda não chegou o meu tempo de entrar triunfalmente em Jerusalém; vós, porém, podeis ir em qualquer ocasião à cidade santa, porque nada tendes a temer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 7, 'O mundo não pode odiar-vos, mas odeia-me a mim, porque faço ver que as suas obras são más.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 8, 'Vós ide a essa festa; eu não vou (publicamente) a essa festa, porque não está ainda completo o meu tempo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 9, 'Tendo dito isto, deixou-se ficar na Galileia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 10, 'Mas, quando seus irmãos já tinham partido, então foi ele também à festa, não descobertamente, mas incógnito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 11, 'Ora os Judeus procuravam-no no dia da festa, e diziam: "Onde está ele?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 12, 'E havia um grande rumor entre o povo acerca dele. Uns diziam: "É um homem de bem." Outros, porém, diziam: "Não é, antes engana o povo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 13, 'Ninguém, contudo, ousava falar dele livremente, com medo dos Judeus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 14, 'Estando já em meio os dias da festa, foi Jesus ao templo, e ensinava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 15, 'Admiravam-se os Judeus, dizendo: "Como sabe este as Escrituras, não tendo estudado?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 16, 'Jesus respondeu-lhes: "A minha doutrina não é minha, mas daquele que me enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 17, 'Se alguém quiser fazer a vontade dele, reconhecerá se a minha doutrina vem de Deus, ou se falo de mim mesmo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 18, 'Quem fala de si mesmo, busca a própria glória; mas aquele que busca a glória de quem o enviou, esse é verdadeiro, e não há nele iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 19, 'Porventura não vos deu Moisés a lei? E, contudo, nenhum de vós observa a lei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 20, 'Porque procurais vós matar-me? "O povo respondeu: "Tu estás possesso do demônio; quem procura matar-te?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 21, 'Jesus replicou-lhes: "Eu fiz uma só obra, e todos estais por isso maravilhados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 22, 'Vós, contudo, porque Moisés vos deu a circuncisão (se bem que ela não vem de Moisés, mas dos patriarcas), circuncidais-vos, mesmo em dia de sábado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 23, 'Se, para não se violar a lei de Moisés, recebe um homem a circuncisão em dia de sábado, porque vos indignais comigo porque em dia de sábado curei um homem em todo o seu corpo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 24, 'Não julgueis segundo a aparência, mas julgai segundo a justiça."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 25, 'Então alguns de Jerusalém diziam: "Não é este aquele que procuram matar?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 26, 'Eis que fala com toda a liberdade e não lhe dizem nada. Será que os chefes do povo tenham verdadeiramente reconhecido que este é o Cristo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 27, 'Nós, porém, sabemos donde este é; e o Cristo, quando vier, ninguém saberá donde ele seja."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 28, 'Jesus, que ensinava no templo, exclamou: "Vós me conheceis, e sabeis donde eu sou... eu não vim de mim mesmo, mas é verdadeiro aquele que me enviou, a quem vós não conheceis. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 29, 'Mas eu conheço-o, porque procedo dele, e ele me enviou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 30, 'Procuraram então prendê-lo; mas ninguém lhe lançou as mãos, porque não tinha ainda chegado a sua hora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 31, 'Muitos do povo creram nele, e diziam: "Quando vier o Cristo, fará ele maior número de prodígios que os que este faz?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 32, 'Os fariseus ouviram este rumor que dele fazia o povo; e os príncipes dos sacerdotes e os fariseus enviaram guardas para o prenderem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 33, 'Jesus disse-lhes: "Ainda por um pouco estou convosco, depois vou para aquele que me enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 34, 'Vós me buscareis, e não me encontrareis; nem vós podeis vir onde eu estou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 35, 'Os Judeus disseram, pois, entre si: "Para onde é que irá ele, que o não encontraremos? Irá, porventura, para os que se acham dispersos entre as nações, e pregará aos gentios?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 36, 'Que quer dizer esta palavra que ele nos disse: Vós me buscareis, e não me encontrareis, e onde eu estou, vós não podeis vir?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 37, 'No ultimo dia, o maior da festa, estava Jesus em pé, e em alta voz dizia: "Se alguém tem sede, venha a mim e beba.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 38, 'O que crê em mim, como diz a Escritura (Is. 44, 3 ; Is. 55, 1 ; Ez. 47, 1 ...) do seu seio correrão rios de água viva."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 39, 'Ora ele dizia isto falando do Espírito que haviam de receber os que cressem nele; porque ainda não tinha sido dado o Espírito, por não ter sido ainda glorificado Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 40, 'Entretanto alguns daquela multidão, tendo ouvido estas palavras, diziam: "Este é verdadeiramente profeta."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 41, 'Outros diziam: "Este é o Cristo." Alguns, porém, diziam: "Porventura é da Galileia que há-de vir o Cristo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 42, 'Não diz a Escritura: Que o Cristo há-de vir da geração de David e da aldeia de Belém, onde habitava David?." (R. 7,12 ; Ps. 88, 3-4 ; Mic. 5, 2)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 43, 'Houve, portanto, dissenção entre o povo acerca dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 44, 'Alguns deles queriam prendê-lo, mas nenhum pôs as mãos sobre ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 45, 'Voltaram, pois, os guardas para os príncipes dos sacerdotes e fariseus, que lhes disseram: "Porque o não trouxestes preso?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 46, 'Os guardas responderam: "Nunca homem algum falou como este homem."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 47, 'Os fariseus replicaram: "Por ventura também vós fostes seduzidos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 48, 'Houve, porventura, algum dentre os chefes do povo ou dos fariseus que cresse nele?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 49, 'Quanto a esta plebe, que não conhece a lei, é maldita."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 50, 'Nicodemos disse-lhes, que era um deles (o que tinha ido de noite ter com Jesus):'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 51, '"A nossa lei condena, porventura, algum homem, antes de o ouvir, e antes de se informar sobre o que ele fez?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 52, 'Responderam: "És tu também galileu? Examina as Escrituras, e verás que da Galileia não sai profeta."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 53, 'E foi cada um para sua casa.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 1, 'Jesus foi para o monte das Oliveiras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 2, 'Ao romper da manhã, voltou para o templo, e todo o povo foi ter com ele, e ele, sentado, os ensinava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 3, 'Então os escribas e os fariseus trouxeram-lhe uma mulher apanhada em adultério; puseram-na no meio,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 4, 'e disseram-lhe: "Mestre, esta mulher foi surpreendida em flagrante delito de adultério.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 5, 'Ora Moisés na lei mandou-nos apedrejar tais mulheres, Que dizes tu, pois?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 6, 'Diziam isto para lhe armar um laço, a fim de o poderem acusar. Porém Jesus, inclinando-se, pôs-se a escrever com o dedo na terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 7, 'Continuando, porém, eles a interrogá-lo, levantou-se, e disse-lhes: "O que de vós está sem pecado, seja o primeiro que lhe atire a pedra."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 8, 'Depois, tornando a inclinar-se, escrevia na terra,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 9, 'Mas eles, ouvindo isto, foram-se retirando, um após outro, começando pelos mais velhos; e ficou só Jesus com a mulher diante dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 10, 'Então Jesus, levantando-se. disse-lhe: "Mulher, onde estão os que te acusavam? Ninguém te condenou?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 11, 'Ela respondeu: "Ninguém, Senhor." Então Jesus disse: "Nem eu te condeno; vai, e não peques mais."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 12, 'Outra vez lhes falou Jesus, dizendo: "Eu sou a luz do mundo; o que me segue não anda nas trevas, mas terá a luz da vida."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 13, 'Os fariseus disseram-lhe: "Tu dás testemunho de ti mesmo; o teu testemunho, por isso, não é verdadeiro."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 14, 'Jesus respondeu: "Embora eu dê testemunho de mim mesmo, o meu testemunho é verdadeiro, porque sei donde vim e para onde vou, mas vós não sabeis donde eu venho, nem para onde vou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 15, 'Vós julgais segundo a carne, eu a ninguém julgo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 16, 'e, se julgo alguém, o meu juízo é verdadeiro, porque eu não sou só, mas eu e o Pai, que me enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 17, 'Na vossa lei está escrito que o testemunho de duas pessoas é digno de fé.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 18, 'Sou eu que dou testemunho de mim mesmo, e meu Pai, que me enviou, também dã testemunho de mim."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 19, 'Disseram-lhe, pois: "Onde está teu Pai?" Jesus respondeu: "Não conheceis nem a mim, nem a meu Pai; se me conhecêsseis a mim, certamente conheceríeis também meu Pai."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 20, 'Estas palavras disse Jesus no lugar do gazofilácio, ensinando no templo; e ninguém o prendeu, porque não tinha ainda chegado a sua hora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 21, 'Jesus disse-lhes mais: "Eu retiro-me: vós me buscareis, e morrereis no vosso pecado. Para onde eu vou, vós não podeis ir."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 22, 'Diziam, pois, os Judeus: "Será que ele se mate a si mesmo, pois diz: Para onde eu vou, vós não podeis ir?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 23, 'Ele disse-lhes: "Vós sois cá de baixo, eu sou lá de cima. Vós sois deste mundo, eu não sou deste mundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 24, 'Por isso eu vos disse que morreríeis nos vossos pecados; sim, se não crerdes em quem eu sou, morrereis no vosso pecado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 25, 'Disseram-lhe então eles: "Quem és tu?" Jesus respondeu-lhes: "É exatamente isso que eu vos estou dizendo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 26, 'Muitas coisas tenho a dizer e a julgar a vosso respeito, mas o que me enviou é verdadeiro, e o que ouvi dele é o que digo ao mundo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 27, 'Eles não compreenderam que Jesus lhes falava do Pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 28, 'Jesus disse-lhes mais: "Quando tiverdes levantado o Filho do homem, então conhecereis quem eu sou, e que nada faço de mim mesmo, mas que, como o Pai me ensinou, assim falo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 29, 'O que me enviou está comigo, não me deixou só, porque eu faço sempre aquilo que é do seu agrado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 30, 'Dizendo ele estas coisas, muitos creram nele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 31, 'Jesus disse então aos Judeus que creram nele: "Se vós permanecerdes na minha palavra, sereis verdadeiramente meus discípulos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 32, 'conhecereis a verdade, e a verdade vos tornará livres."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 33, 'Eles responderam-lhe: "Nós somos descendentes de Abraão, e nunca fomos escravos de ninguém; como dizes tu: Sereis livres?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 34, 'Jesus respondeu-lhes: "Em verdade, em verdade vos digo que todo o que comete o pecado, é escravo do pecado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 35, 'Ora o escravo não fica para sempre na casa, mas o filho fica nela para sempre. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 36, 'Por isso, se o filho vos livrar, sereis verdadeiramente livres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 37, 'Bem sei que sois descendentes de Abraão; mas procurais matar-me, porque a minha palavra não penetra em vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 38, 'Eu digo o que vi em meu Pai; e vós fazeis o que ouvistes do vosso pai."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 39, 'Eles replicaram: "O nosso pai é Abraão." Jesus disse-lhes: "Se sois filhos de Abraão, fazei as obras de Abraão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 40, 'Mas agora procurais matar-me, a mim, que vos disse a verdade que ouvi de Deus. Abraão nunca fez isto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 41, 'Vós fazeis as obras de vosso pai. "Eles disseram-lhe: "Nós não somos filhos da fornicação: temos um pai que é Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 42, 'Jesus disse-lhes: "Se Deus fosse vosso pai, certamente me amaríeis, porque eu saí e vim de Deus. Não vim de mim mesmo, mas ele me enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 43, 'Porque não conheceis vós a minha linguagem? Porque não podeis ouvir a minha palavra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 44, 'Vós tendes por pai o demônio, e quereis satisfazer os desejos do vosso pai. Ele foi homicida desde o principio, e não permaneceu na verdade, porque a verdade não está nele. Quando ele diz a mentira, fala do que é próprio, porque é mentiroso e pai da mentira.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 45, 'Mas, ainda que eu vos diga a verdade, vós não me credes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 46, 'Qual de vós me arguirá de pecado? Se eu vos digo a verdade, porque me não credes?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 47, 'O que é de Deus ouve as palavras de Deus; por isso vós não as ouvis porque não sois de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 48, 'Os Judeus responderam-lhe: "Não dizemos nós com razão que tu és um samaritano e que tens demônio?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 49, 'Jesus respondeu: "Eu não tenho demônio, mas honro o meu Pai, e vós a mim desonrastes-me.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 50, 'Eu não busco a minha glória; há quem tome cuidado dela, e quem fará justiça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 51, 'Em verdade, em verdade voz digo; quem guardar a minha palavra não verá a morte eternamente."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 52, 'Os Judeus disseram-lhe: "Agora reconhecemos que estás possesso do demônio. Abraão morreu, os profetas também e tu dizes: Quem guardar a minha palavra não provará a morte eternamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 53, 'Porventura és maior do que nosso pai Abraão, que morreu? Os profetas também morreram. Quem pretendes tu ser?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 54, 'Jesus respondeu: "Se eu me glorifico a mim mesmo, não é nada a minha glória; meu Pai é que me glorifica, aquele que vós dizeis que é vosso Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 55, 'Mas vós não o conhecestes; eu sim, conheço-o; e se disser que o não conheço serei mentiroso como vós. Mas conheço-o e guardo a sua palavra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 56, 'Abraão, vosso pai, regozijou-se com a esperança de ver o meu dia; viu-o (por meio da, revelação), e ficou cheio de gozo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 57, 'Os Judeus, por isso, disseram-lhe: "Tu ainda não tens cinquenta anos, e viste Abraão!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 58, 'Jesus disse-lhes: "Em verdade, em verdade vos digo: Antes que Abraão fosse feito, eu sou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 59, 'Então pegaram em pedras para lhe atirarem; mas Jesus encobriu-se e saiu do templo.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 1, 'Passando Jesus, viu um homem cego de nascença.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 2, 'Os seus discípulos perguntaram-lhe: "Mestre, quem pecou, este ou seus pais, para que nascesse cego?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 3, 'Jesus respondeu: "Nem ele nem seus pais pecaram; mas foi para se manifestarem nele as obras de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 4, 'Importa que eu faça as obras daquele que me enviou, enquanto é dia ; vem a noite, quando ninguém pode trabalhar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 5, 'Enquanto estou no mundo, sou a luz do mundo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 6, 'Dito isto, cuspiu no chão, fez lodo com a saliva, e ungiu com o lodo os olhos do cego.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 7, 'Depois disse-lhe: "Vai, lava-te na piscina de Siloé (que quer dizer Enviado)." Foi, lavou-se e voltou com vista.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 8, 'Então os seus vizinhos e os que o tinham visto antes pedindo esmola, diziam: "Não é este aquele que estava sentado e pedia esmola?" Outros diziam : "É este."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 9, 'Outros porém: "Não é, mas é outro, que se parece com ele." Porém ele dizia: "Sou eu."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 10, 'Perguntaram-lhe: "Como te foram abertos os olhos?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 11, 'Ele respondeu: "Aquele homem, que se chama Jesus, fez lodo, ungiu os meus olhos e disse-me: Vai à piscina de Siloé, e lava-te. Fui, lavei-me, e vejo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 12, 'Perguntaram-lhe: "Onde está ele?" Respondeu: "Não sei."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 13, 'Levaram aos fariseus o que tinha sido cego.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 14, 'Ora era dia de sábado quando Jesus fez o lodo e lhe abriu os olhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 15, 'Perguntaram-lhe, pois, também os fariseus de que modo tinha adquirido a vista. Respondeu-lhes: "Pôs-me lodo sobre os olhos, lavei-me, e vejo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 16, 'Então, alguns fariseus, diziam: "Este homem, que não guarda o sábado, não é de Deus." Porém outros diziam: "Como pode um homem pecador fazer tais prodígios?" E havia dissenção entre eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 17, 'Disseram, por isso, novamente ao cego: "Tu que dizes daquele que te abriu os olhos?" Ele respondeu: "Que é um profeta."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 18, 'Mas os Judeus não acreditaram que ele tivesse sido cego e tivesse adquirido a vista, enquanto não chamaram seus pais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 19, 'Interrogaram-nos: "É este o vosso filho que vós dizeis que nasceu cego? Como vê, pois, agora?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 20, 'Seus pais responderam-lhe: "Sabemos que este é nosso filho, e que nasceu cego;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 21, 'mas não sabemos como ele agora vê, ou quem lhe abriu os olhos não sabemos também; perguntai-o a ele mesmo; tem idade, ele mesmo fale de si."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 22, 'Seus pais falaram assim, porque tinham medo dos Judeus; porque estes tinham combinado que se alguém confessasse que Jesus era o Cristo, fosse expulso da sinagoga.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 23, 'Por isso é que seus pais disseram: "Ele tem idade, interrogai-o a ele."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 24, 'Tornaram, pois, a chamar o homem que tinha sido cego, e disseram-lhe: "Dá glória a Deus; nós sabemos que esse homem é um pecador."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 25, 'Então disse-lhes ele: "Se é pecador, não sei, o que eu sei é que era cego, e agora vejo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 26, 'Disseram-lhe pois: "Que é que te fez ele? Como te abriu os olhos?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 27, 'Respondeu-lhes; "Eu já vo-lo disse, e vós não me destes atenção; porque o quereis ouvir novamente? Quereis, porventura, fazer-vos também seus discípulos?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 28, 'Injuriaram-no então, e disseram: "Discípulo dele sejas tu; nós somos discípulos de Moisés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 29, 'Sabemos que Deus falou a Moisés; mas este não sabemos donde é."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 30, 'O homem respondeu-lhes: "É de admirar que vós não saibais donde ele é, e que me tenha aberto os olhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 31, 'Nós sabemos que Deus não ouve os pecadores; mas quem honra a Deus e faz a sua vontade, esse é ouvido por Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 32, 'Desde que há mundo, nunca se ouviu dizer que alguém abrisse os olhos a um cego de nascença.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 33, 'Se este não fosse de Deus, não podia fazer nada."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 34, 'Responderam-lhe: "Tu nasceste coberto de pecados, e queres-nos ensinar?" E lançaram-no fora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 35, 'Jesus ouviu dizer que o tinham lançado fora, e, tendo-o encontrado, disse-lhe: "Tu crês no Filho de Deus?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 36, 'Ele respondeu: "Quem é, Senhor, para eu crer nele?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 37, 'Jesus disse-lhe: "Tu o vês, é aquele mesmo que fala contigo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 38, 'Então ele disse: "Creio, Senhor." E, prostrando-se, o adorou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 39, 'Jesus disse: "Eu vim a este mundo para exercer um justo juízo, a fim de que os que não vêem vejam, e os que vêem se tornem cegos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 40, 'Ouviram isto alguns dos fariseus, que estavam com ele, e disseram-lhe: "Porventura também nós somos cegos?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 41, 'Jesus disse- lhes: "Se vós fosseis cegos, não teríeis culpa; mas, pelo contrário, vós dizeis: Nós vemos. Fica, pois subsistindo o vosso pecado.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 1, 'Em verdade, em verdade, vos digo que quem não entra pela porta no aprisco das ovelhas, mas sobe por outra parte, é ladrão e salteador.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 2, 'O que entra pela porta, é pastor das ovelhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 3, 'A este o porteiro abre, e as ovelhas ouvem a sua voz, ele as chama pelo seu nome, e as tira para fora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 4, 'Quando as tirou todas para fora, vai adiante delas, e as ovelhas seguem-no, porque conhecem a sua voz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 5, 'Mas não seguem o estranho, antes fogem dele, porque não conhecem a voz dos estranhos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 6, 'Jesus disse-lhes esta alegoria, mas eles não compreenderam o que lhes dizia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 7, 'Tornou, pois, Jesus a dizer-lhes: "Em verdade, em verdade, vos digo que eu sou a porta das ovelhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 8, 'Todos os que vieram antes de mim são ladrões e salteadores; mas as ovelhas não os ouviram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 9, 'Eu sou a porta; se alguém entrar por mim, será salvo; entrará, e sairá, e encontrará pastagens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 10, 'O ladrão não vem senão para roubar, matar e destruir. Eu vim para que elas tenham vida e estejam na abundância.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 11, 'Eu sou o bom pastor. O bom pastor expõe a sua vida pelas suas ovelhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 12, 'O mercenário, o que não é pastor, de quem não são próprias as ovelhas, vê vir o lobo, deixa as ovelhas, e foge; e o lobo arrebata e faz desgarrar as ovelhas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 13, 'porque é mercenário, e porque não se importa com as ovelhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 14, 'Eu sou o bom pastor, e conheço as minhas ovelhas, e as minhas ovelhas conhecem-me.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 15, 'Como o Pai me conhece, assim eu conheço o Pai; e dou a minha vida pelas minhas ovelhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 16, 'Tenho outras ovelhas que não são deste aprisco; importa que eu as traga; elas ouvirão a minha voz, e haverá um só rebanho e um só pastor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 17, 'Se o Pai me ama, é porque dou a minha vida para outra vez a assumir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 18, 'Ninguém me tira, mas eu por mim mesmo a dou, e tenho poder de a dar, e tenho poder de a reassumir. Este é o mandamento que recebi de meu Pai."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 19, 'Originou-se por causa destas palavras uma nova dissenção entre os Judeus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 20, 'Muitos deles diziam: "Ele está possesso do demônio; delira; porque estais a ouvi-lo?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 21, 'Outros diziam: "Estas palavras não são de quem está possesso do demônio. Porventura pode o demônio abrir os olhos aos cegos?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 22, 'Celebrava-se em Jerusalém a festa da dedicação. Era inverno.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 23, 'Jesus andava passeando no templo, no pórtico de Salomão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 24, 'Rodearam-no os Judeus, e disseram-lhe: "A té quando nos terás tu perplexos? Se és o Cristo, dize-no-lo claramente."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 25, 'Jesus respondeu-lhes: "Eu digo-vo-lo, e vós não me credes. As obras que faço em nome de meu Pai, essas dão testemunho de mim;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 26, 'porém vós não credes, porque não sois das minhas ovelhas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 27, 'As minhas ovelhas ouvem a minha voz; eu conheço-as, e elas seguem-me.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 28, 'Eu dou-lhes a vida eterna; elas jamais hão-de perecer, e ninguém as arrebatará da minha mão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 29, 'Meu Pai, que me deu, é maior que todas as coisas; e ninguém pode arrebatá-las da mão de meu Pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 30, 'Eu e o Pai somos um."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 31, 'Os Judeus, então, pegaram em pedras para lhe atirarem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 32, 'Jesus disse-lhes: "Tenho-vos mostrado muitas obras boas que fiz por virtude de meu Pai; por qual destas obras me apedrejais?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 33, 'Os Judeus responderam-lhe: "Não é por causa de nenhuma obra boa que te apedrejamos, mas pela blasfêmia, e porque sendo homem, te fazes Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 34, 'Jesus respondeu-lhes: "Não está escrito na vossa lei: Eu disse: Vós sois deuses? (Ps. 81, 6)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 35, 'Se ela chamou deuses àqueles a quem a palavra de Deus foi dirigida, e a Escritura não pode falhar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 36, 'a mim, a quem o Pai santificou e enviou ao mundo, vós dizeis: Tu blasfemas, por eu ter dito: Sou filho de Deus?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 37, 'Se eu não faço as obras de meu Pai, não me acrediteis;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 38, 'mas se as faço, quando não queirais crer em mim, crede nas minhas obras, para que saibais e reconheçais que o Pai está em mim, e eu no Pai."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 39, 'Então os Judeus procuravam novamente prendê-lo, mas ele escapou-se das suas mãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 40, 'Retirou-se novamente para a banda de além do Jordão, para o lugar em que João tinha começado a baptizar; e ficou lá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 41, 'Foram muitos ter com ele, e diziam: "João não fez nenhum milagre,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 42, 'mas tudo o que disse deste era verdadeiro." E muitos creram nele.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 1, 'Estava enfermo um homem, chamado Lázaro, de Betânia, aldeia de Maria e de Marta, sua irmã.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 2, 'Maria era aquela que ungiu o Senhor com bálsamo, e lhe enxugou os pés com os seus cabelos, cujo irmão Lázaro estava enfermo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 3, 'Mandaram, pois, suas irmãs dizer a Jesus: "Senhor, aquele que amas está enfermo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 4, 'Ouvindo isto, Jesus disse: "Esta enfermidade não é de morte, mas é para glória de Deus, a fim de que o Filho de Deus seja glorificado por ela."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 5, 'Ora Jesus amava Marta, sua irmã Maria e Lázaro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 6, 'Tendo, pois, ouvido que Lázaro estava enfermo, ficou ainda dois dias no mesmo lugar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 7, 'Depois disto, disse a seus discípulos: "Voltemos para a Judeia."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 8, 'Os discípulos disseram-lhe: "Mestre, ainda há pouco te queriam apedrejar os Judeus, e tu vais novamente para lá?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 9, 'Jesus respondeu: "Não são doze as horas do dia? Aquele que caminhar de dia, não tropeça, porque vê a luz deste mundo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 10, 'porém, o que andar de noite tropeça, porque lhe falta a luz."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 11, 'Assim falou, depois disse-lhes: ''Nosso amigo Lázaro dorme; mas vou despertá-lo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 12, 'Os seus discípulos disseram-lhe: "Senhor, se ele dorme, curar-se-á."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 13, 'Mas Jesus tinha falado da sua morte; e eles julgavam que falava do repouso do sono.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 14, 'Jesus disse-lhes então claramente: "Lázaro morreu,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 15, 'e eu, por amor de vós, folgo não ter estado lá para que creiais; mas vamos ter com ele."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 16, 'Tomé, chamado Dídimo, disse então aos condiscípulos: "Vamos nós também para morrer com ele."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 17, 'Chegou Jesus, e encontrou-o já há quatro dias no sepulcro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 18, 'Betânia distava de Jerusalém cerca de quinze estádios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 19, 'Muitos Judeus tinham ido ter com Marta e Maria, para lhes dar os pêsames pela morte de seu irmão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 20, 'Marta, pois, logo que ouviu que vinha Jesus, saiu-lhe ao encontro; e Maria ficou em casa sentada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 21, 'Marta disse então a Jesus: "Senhor, se tu estivesses cá, meu irmão não teria morrido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 22, 'Mas também sei agora que tudo o que pedires a Deus, Deus to concederá."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 23, 'Jesus disse-lhe: "Teu irmão há-de ressuscitar."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 24, 'Marta disse-lhe: "Eu sei que há-de ressuscitar na ressurreição do último dia."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 25, 'Jesus disse-lhe: "Eu sou a ressurreição e a vida; o que crê em mim, ainda que esteja morto, viverá;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 26, 'e todo o que vive e crê em mim, não morrerá eternamente. Crês isto?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 27, 'Ela respondeu: "Sim, Senhor, eu creio que tu és o Cristo, o Filho de Deus, que devia vir a este mundo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 28, 'Dito isto, retirou-se, e foi chamar em segredo sua irmã Maria, dizendo: "O Mestre está cá, e chama-te."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 29, 'Ela, logo que ouviu isto, levantou-se rapidamente, e foi ter com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 30, 'Jesus ainda não tinha entrado na aldeia, mas estava ainda naquele lugar, onde Marta saíra ao seu encontro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 31, 'Então os Judeus, que estavam com ela em casa, e a consolavam, vendo que Maria se tinha levantado tão depressa e tinha saído, seguiram-na, julgando que ia chorar ao sepulcro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 32, 'Maria, porém, tendo chegado onde Jesus estava, logo que o viu, lançou-se aos seus pés, e disse-lhe:"Senhor, se tivesses estado aqui, não teria morrido meu irmão."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 33, 'Jesus, vendo-a chorar, a ela e aos Judeus, que tinham ido com ela, comoveu-se profundamente e perturbou-se;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 34, 'depois perguntou: "Onde o pusestes?" Eles responderam: "Senhor, vem ver."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 35, 'Jesus chorou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 36, 'Os Judeus, por isso, disseram: "Vejam como ele o amava."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 37, 'Porém alguns deles disseram: "Este, que abriu os olhos ao que era cego de nascença, não podia fazer que este não morresse?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 38, 'Jesus, pois, novamente comovido no seu interior, foi ao sepulcro. Era este uma gruta à qual estava sobreposta uma pedra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 39, 'Jesus disse: "Tirai a pedra." Marta, irmã do defunto, disse-lhe: "Senhor, ele já cheira mal, porque já aí está há quatro dias."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 40, 'Jesus disse-lhe: "Não te disse eu que, se tu creres, verás a glória de Deus?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 41, 'Tiraram, pois, a pedra. Jesus, levantando os olhos ao céu, disse: "Pai, dou-te graças, porque me tens ouvido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 42, 'Eu bem sabia que me ouves sempre, mas falei assim por causa do povo que está à roda de mim, para que creiam que tu me enviaste."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 43, 'Tendo dito estas palavras, bradou em alta voz: "Lázaro, sai para fora."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 44, 'E saiu o que estivera morto, ligado de pés e mãos com as ataduras, e o seu rosto envolto num sudário. Jesus disse-lhes: "Desligai-o e deixai-o ir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 45, 'Então muitos dos Judeus que tinham ido visitar Maria e Marta, vendo o que Jesus fizera, creram nele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 46, 'Porém alguns deles foram ter com os fariseus, e contaram-lhes o que Jesus tinha feito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 47, 'Os pontífices e os fariseus reuniram-se então em conselho, e diziam: "Que fazemos nós? Este homem faz muitos milagres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 48, 'Se o deixamos proceder assim, crerão todos nele; e virão os Romanos e destruirão a nossa cidade e a nossa nação."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 49, 'Mas um deles, chamado Caifás, que era o pontífice daquele ano, disse-lhes: "Vós não sabeis nada,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 50, 'nem considerais que vos convém que morra um homem pelo povo, e que não pereça toda a nação."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 51, 'Ora ele não disse isto por si mesmo, mas, como era pontífice daquele ano, profetizou que Jesus devia morrer pela nação,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 52, 'e não somente pela nação, mas também para unir num só corpo os filhos de Deus dispersos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 53, 'Desde aquele dia tomaram a resolução de o matar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 54, 'Jesus, pois, já não andava em público entre os Judeus, mas retirou-se para uma terra vizinha do deserto, para a cidade chamada Efraim e lã esteve com seus discípulos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 55, 'Estava próxima a Páscoa dos Judeus, e muitos daquela terra subiram a Jerusalém antes da Páscoa para se purificarem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 56, 'Procuravam Jesus, e diziam uns para os outros, estando no templo: "Que vos parece de ele não ter vindo à festa?" Ora os pontífices e fariseus tinham passado ordem que quem soubesse onde ele estava, o denunciasse para o prenderem.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 1, 'Seis dias antes da Páscoa, Jesus foi a Betânia, onde se encontrava Lázaro, que Jesus tinha ressuscitado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 2, 'Deram-lhe lá uma ceia. Marta servia, e Lázaro era um dos que estavam à mesa com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 3, 'Então tomou Maria uma libra de bálsamo feito de nardo puro de grande preço, ungiu os pés de Jesus e enxugou-lhos com os seus cabelos; e a casa ficou cheia de perfume do bálsamo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 4, 'Judas Iscariotes, um dos seus discípulos, aquele que o havia de entregar, disse:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 5, '"Porque se não vendeu este bálsamo por trezentos dinheiros, para se dar aos pobres?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 6, 'Disse isto, não porque se importasse com os pobres, mas porque era ladrão, e, tendo a bolsa, roubava o que se lançava nela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 7, 'Mas Jesus respondeu: "Deixa-a; ela reservou este perfume para o dia da minha sepultura;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 8, 'porque sempre tereis pobres convosco, mas a mim não me tereis sempre."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 9, 'Uma grande multidão de Judeus soube que Jesus estava ali e foi lá, não somente por causa de Jesus, mas também para ver Lázaro, a quem ele tinha ressuscitado dos mortos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 10, 'Os príncipes dos sacerdotes deliberaram então matar também Lázaro,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 11, 'porque muitos Judeus, por causa dele, retiravam-se e criam em Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 12, 'No dia seguinte, uma grande multidão de povo, que tinha ido à festa, ouvindo dizer que Jesus ia a Jerusalém,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 13, 'tomou ramos de palmas, saiu ao seu encontro e clamava: "Hosana! Bendito o que vem em nome do Senhor, o rei de Israel."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 14, 'Jesus encontrou um jumentinho, e montou em cima dele, segundo está escrito:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 15, 'Não temas, filha de Sião; eis que o teu Rei vem montado sobre um jumentinho (Zc. 9, 9).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 16, 'A princípio, os seus discípulos não compreenderam estas coisas, mas quando Jesus foi glorificado, então lembraram-se de que estas coisas tinham sido escritas dele e que eles mesmos tinham contribuído para o seu cumprimento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 17, 'A multidão que estava com ele, quando chamou Lázaro do sepulcro e o ressuscitou dos mortos, dava testemunho dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 18, 'Por isso, lhe saiu ao encontro a multidão, porque ouviram dizer que tinha feito este milagre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 19, 'Então os fariseus disseram entre si: "Vedes que nada aproveitais? Eis que todos correm atrás dele."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 20, 'Ora havia lá alguns Gregos, entre aqueles que tinham ido adorar a Deus durante a festa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 21, 'Estes aproximaram-sé de Filipe, que era de Betsaida da Galileia, e fizeram-lhe este pedido: "Senhor, desejamos ver Jesus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 22, 'Filipe foi dizê-lo a André; André e Filipe disseram-no a Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 23, 'Jesus respondeu-lhes: "Chegou a hora em que o Filho do homem será glorificado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 24, 'Em verdade, em verdade, vos digo, que se o grão de trigo, que cai na terra, não morrer,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 25, 'fica infecundo; mas, se morrer, produz muito fruto. O que ama a sua vida, perdê-la-á, e quem aborrece a sua vida neste mundo, conservá-la-á para a vida eterna,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 26, 'Se alguém me quer servir, siga-me, e, onde eu estou, estará ali também o que me serve. Se alguém me servir, meu Pai o honrará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 27, 'Agora a minha alma, está turbada. E que direi eu? Pai, livra-me desta hora. Mas é para isso que cheguei a esta hora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 28, 'Pai, glorifica o teu nome. " Então veio do céu esta voz: "Eu o glorifiquei e o glorificarei novamente."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 29, 'Ora o povo, que ali estava e ouvira, dizia que linha sido um trovão. Outros diziam: Um anjo lhe falou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 30, 'Jesus respondeu; "Esta voz não veio por amor de mim, mas por amor de vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 31, 'Agora é o juízo deste mundo; agora será lançado fora o príncipe deste mundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 32, 'E eu, quando for levantado da terra, atrairei todos os homens a mim."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 33, 'Dizia isto para designar de que morte havia de morrer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 34, 'Respondeu-lhe a multidão: "Nós aprendemos da lei que o Cristo permanece eternamente; como dizes tu que o Filho do homem deve ser levantado? Quem é este Filho do homem?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 35, 'Jesus respondeu-lhes: "Ainda por um pouco de tempo está a luz convosco. Andai enquanto tendes a luz, para que não vos surpreendam as trevas; quem caminha nas trevas, não sabe onde vai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 36, 'Enquanto tendes a luz, crede na luz para que sejais filhos da luz." Jesus disse isto; depois retirou-se e escondeu-se deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 37, 'Apesar de haver ele feito tantos milagres em sua presença, não criam nele,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 38, 'para se cumprir a palavra do profeta Isaías (Is. 53, 1), quando disse: Senhor, quem acreditou o que ouviu de nós? E a quem foi revelado o braço do Senhor?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 39, 'Por isso não podiam crer, porque Isaías disse também (Is. 6, 9-10):'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 40, 'Tornou-lhes cegos os olhos, endureceu-lhes o coração, para que não vejam com os olhos, não compreendam com o coração, não se convertam e eu não os sare. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 41, 'Isto disse Isaías, quando viu a sua glória e falou dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 42, 'Todavia, mesmo entre os principais, muitos creram nele; mas, por causa dos fariseus, não o confessavam para não serem expulsos da sinagoga.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 43, 'Porque amaram mais a glória dos homens do que a glória de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 44, 'Jesus levantou a voz e disse: "O que crê em mim, não crê em mim, mas naquele que me enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 45, 'Quem me vê a mim, vê aquele que me enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 46, 'Eu vim ao mundo como uma luz, para que todo o que crê em mim não fique nas trevas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 47, 'Se alguém ouvir as minhas palavras e não as guardar, eu não o julgo, porque não vim para julgar o mundo, mas para salvar o mundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 48, 'O que me despreza e não recebe as minhas palavras, já tem quem o julgue; a palavra que anunciei, essa o julgará no último dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 49, 'Com efeito, eu não falei por mim mesmo, mas o Pai que me enviou, ele mesmo me prescreveu o que eu devia dizer e ensinar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 50, 'Eu sei que o seu mandamento é a vida eterna. As coisas, pois, que digo, digo-as como meu Pai me disse.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 1, 'Antes da festa da Páscoa, sabendo Jesus que tinha chegado a sua hora de passar deste mundo ao Pai, tendo amado os seus, que estavam no mundo, amou-os até ao extremo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 2, 'Durante a ceia, tendo já o demônio posto no coração de Judas Iscariotes, filho de Simão, a determinação de o entregar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 3, 'Jesus, sabendo que o Pai tinha posto em suas mãos todas as coisas, que saíra de Deus e voltava para Deus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 4, 'levantou-se da mesa, depôs as vestes, e, pegando numa toalha, cingiu-se com ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 5, 'Depois lançou água numa bacia, e começou a lavar os pés dos discípulos e a enxugá-los, com a toalha com que estava cingido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 6, 'Chegou, pois, a Simão Pedro. Pedro disse-lhe: "Senhor, tu lavares-me os pés?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 7, 'Jesus respondeu-lhe: "O que eu faço, tu não o compreendes agora, mas compreendê-lo-ás depois."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 8, 'Pedro disse-lhe: "Não me lavarás jamais os pés." Jesus respondeu-lhe: "Se eu não te lavar, não terás parte comigo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 9, 'Simão Pedro disse-lhe: "Senhor, não somente os meus pés, mas também as mãos e a cabeça."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 10, 'Jesus disse-lhe: "Aquele que se banhou, não tem necessidade de se lavar, pois todo ele está limpo. Vós estais limpos, mas não todos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 11, 'Ele sabia qual era o que o ia entregar, por isso disse: "Não estais todos limpos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 12, 'Depois que lhes lavou os pés e que retomou as suas vestes, tendo-se tornado a pôr à mesa disse-lhes: "Compreendeis o que vos fiz?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 13, 'Chamais-me Mestre e Senhor, e dizeis bem, porque o sou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 14, 'Se eu, pois, sendo vosso Senhor e Mestre, vos lavei os pés, também vós deveis lavar os pés uns aos outros. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 15, 'Dei-vos o exemplo, para que, como eu vos fiz, assim façais vós também.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 16, 'Em verdade, em verdade, vos digo: O servo não é maior do que seu senhor, nem o enviado é maior do que aquele que o enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 17, 'Se compreendeis estas coisas, bem-aventurados sereis se as praticardes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 18, 'Não falo de todos vós; sei os que escolhi; porém é necessário que se cumpra o que diz a Escritura: O que come o pão comigo levantará o seu calcanhar contra mim (Ps. 40, 10).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 19, 'Desde agora vo-lo digo, antes que suceda, para que, quando suceder, creiais que sou eu (o Messias).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 20, 'Em verdade, em verdade, vos digo, que quem recebe aquele que eu enviar, a mim recebe, e o que me recebe, recebe aquele que me enviou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 21, 'Tendo Jesus dito estas coisas, turbou-se em seu espírito e declarou abertamente: "Em verdade, em verdade, vos digo, que um de vós me há-de entregar."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 22, 'Olhavam, pois, os discípulos uns para os outros, não sabendo de quem falava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 23, 'Ora um dos seus discípulos, ao qual Jesus amava, estava recostado sobre o seio de Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 24, 'A este fez Simão Pedro sinal, para lhe dizer: "De quem fala ele?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 25, 'Aquele discípulo, pois, tendo-se reclinado sobre o peito de Jesus, disse-lhe: "Senhor, quem é esse?" (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 26, 'Jesus respondeu; "É aquele a quem eu der o bocado que vou molhar." Molhando, pois, o bocado, deu-o a Judas Iscariotes, filho de Simão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 27, 'Atrás do bocado, entrou nele Satanás. Jesus disse-lhe então: "O que queres fazer, faze-o depressa."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 28, 'Nenhum, porém, dos que estavam à mesa percebeu por que lhe dizia isto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 29, 'Alguns, como Judas era o que tinha a bolsa, julgavam que Jesus lhe dissera: "Compra as coisas que nos são precisas para o dia da festa", ou: "Dá alguma coisa aos pobres."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 30, 'Ele, pois, tendo recebido o bocado, saiu logo. Era já noite.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 31, 'Depois que ele saiu, Jesus disse: "Agora é glorificado o Filho do homem, e Deus é glorificado nele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 32, 'Se Deus foi glorificado nele, também Deus o glorificará em si mesmo; e glorificá-lo-á sem demora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 33, 'Filhinhos já pouco tempo estou convosco. Buscar-me-eis, mas, assim como disse aos Judeus: Para onde eu vou, vós não podeis vir, também a vós o digo agora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 34, 'Dou-vos um novo mandamento: Que vos ameis uns aos outros, que, assim como vos amei, vos ameis também uns aos outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 35, 'Nisto conhecerão todos que sois meus discípulos, se tiverdes amor uns aos outros."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 36, 'Simão Pedro disse-lhe: "Senhor, para onde vais tu?" Jesus respondeu-lhe: "Para onde eu vou, não podes tu agora seguir-me, mas seguir-me-ás mais tarde."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 37, 'Pedro disse-lhe: "Porque não posso eu seguir-te agora? Darei a minha vida por ti."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 38, 'Jesus respondeu-lhe:"Darás a tua vida por mim? Em verdade, em verdade, te digo: Não cantará o galo sem que me tenhas negado três vezes.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 1, 'Não se turbe o vosso coração. Credes em Deus, crede também em mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 2, 'Na casa de meu Pai há muitas moradas. Se assim não fosse, eu vo-lo teria dito. Vou preparar um lugar para vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 3, 'Depois que eu tiver ido e vos tiver preparado um lugar, virei novamente e tomar-vos-ei comigo, para que, onde eu estou, estejais vós também.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 4, 'E vós conheceis o caminho para ir onde eu vou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 5, 'Tomé disse-lhe: "Senhor, nós não sabemos para onde vais; como podemos saber o caminho?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 6, 'Jesus disse-lhe: "Eu sou o caminho, a verdade e a vida; ninguém vai ao Pai senão por mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 7, 'Se me conhecêsseis, também certamente conheceríeis meu Pai; mas desde agora o conheceis e já o vistes."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 8, 'Filipe disse-lhe: "Senhor, mostra-nos o Pai, e isso nos basta."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 9, 'Jesus disse-lhe: "Há tanto tempo que estou convosco, e ainda não me conheceste, Filipe? Quem me viu, viu também o Pai. Como dizes pois: Mostra-nos o Pai?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 10, 'Não credes que eu estou no Pai, e que o Pai está em mim? As palavras que vos digo, não as digo de mim mesmo. O Pai, que está em mim, esse é que faz as obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 11, 'Crede em mim: eu estou no Pai, e o Pai está em mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 12, 'Crede-o ao menos por causa das mesmas obras. Em verdade, em verdade, vos digo, que aquele que crê em mim fará também as obras que eu faço. Fará outras ainda maiores, porque eu vou para o Pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 13, 'Tudo o que pedirdes em meu nome, eu o farei, para que o Pai seja glorificado no Filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 14, 'Se me pedirdes alguma coisa em meu nome, eu a farei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 15, 'Se me amais, observareis os meus mandamentos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 16, 'e eu rogarei ao Pai, e ele vos dará um outro Paráclito, para que fique eternamente convosco,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 17, 'o Espírito de verdade, a quem o mundo não pode receber, porque não o vê, nem o conhece; mas vós o conheceis, porque habita convosco e estará em vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 18, 'Não vos deixarei órfãos; voltarei a vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 19, 'Resta ainda um pouco, e depois já o mundo me não verá. Mas ver-me-eis vós, porque eu vivo, e vós vivereis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 20, 'Naquele dia conhecereis que estou em meu Pai, e vós em mim, e eu em vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 21, 'Aquele que retém os meus mandamentos e os guarda, esse é que me ama; e aquele que me ama, será amado por meu Pai, e eu o amarei, e me manifestarei a ele."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 22, 'Judas disse-lhe (não o Iscariotes): "Senhor, qual é a causa por que te hás-de manifestar a nós, e não ao mundo?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 23, 'Jesus respondeu-lhe: "Se alguém me ama, guardará a minha palavra, e meu Pai o amará, e nós viremos a ele, e faremos nele a nossa morada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 24, 'O que não me ama, não observa as minhas palavras. E a palavra que ouvistes, não é minha, mas do Pai, que me enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 25, 'Disse-vos estas coisas, permanecendo convosco.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 26, 'Mas o Paráclito, o Espírito Santo, a quem o Pai enviará em meu nome, ele vos ensinará todas as coisas, e vos recordará tudo o que vos tenho dito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 27, 'Deixo-vos a paz, dou-vos a minha paz; não vo-la dou, como a dá o mundo. Não se turbe o vosso coração, nem se assuste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 28, 'Ouviste que eu vos disse: Vou e voltarei a vós. Se vós me amásseis, certamente vos alegraríeis de eu ir para o Pai, porque o Pai é maior do que eu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 29, 'Eu vo-lo disse agora, antes que suceda, para que, quando suceder, acrediteis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 30, 'Já não falarei muito convosco, porque vem o príncipe deste mundo. Ele não pode nada contra mim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 31, 'mas é preciso que o mundo conheça que amo o Pai e que faço como ele me ordenou. Levantai-vos, vamo-nos daqui.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 1, 'Eu sou a verdadeira vide, e meu Pai é o vinhateiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 2, 'Toda a vara que não dá fruto em mim, ele a cortará; e toda a que der fruto, podá-la-á, para que dê mais abundante fruto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 3, 'Vós já estais puros em virtude da palavra que vos anunciei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 4, 'Permanecei em mim, e eu permanecerei em vós. Como a vara não pode de si mesma dar fruto, se não permanecer na videira, assim também vós, se não permanecerdes em mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 5, 'Eu sou a videira, vós as varas. O que permanece em mim e eu nele, esse dá muito fruto, porque, sem mim, nada podeis fazer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 6, 'Se alguém não permanecer em mim, será lançado fora, como a vara, e secará; depois enfeixá-lo-ão, lançá-lo-ão no fogo, e arderá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 7, 'Se permanecerdes em mim, e as minhas palavras permanecerem em vós, pedireis tudo o que quiserdes, e ser-vos-á concedido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 8, 'Nisto é glorificado meu Pai, em que vós deis muito fruto e sejais meus discípulos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 9, 'Como o Pai me amou, assim eu vos amei. Permanecei no meu amor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 10, 'Se observardes os meus preceitos, permanecereis no meu amor, como eu observei os preceitos de meu Pai, e permaneço no seu amor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 11, 'Disse-vos estas coisas, para que a minha alegria esteja em vós, e para que a vossa alegria seja completa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 12, 'O meu preceito é este: Amai-vos uns aos outros, como eu vos amei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 13, 'Não há maior amor do que dar a própria vida pelos seus amigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 14, 'Vós sois meus amigos, se fizerdes o que vos mando.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 15, 'Não mais vos chamarei servos, porque o servo não sabe o que faz o seu senhor; mas chamo-vos amigos, porque vos dei a conhecer tudo o que ouvi de meu Pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 16, 'Não fostes vós que me escolhestes, mas fui eu que vos escolhi a vós, e vos destinei para que vades e deis fruto, e para que o vosso fruto permaneça, a fim de que tudo o que pedirdes a meu Pai em meu nome, ele vo-lo conceda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 17, 'Isto vos mando: Amai-vos uns aos outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 18, 'Se o mundo vos aborrece, sabei que, primeiro do que a vós, me aborreceu a mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 19, 'Se fosseis do mundo, o mundo amaria o que era seu; mas, porque não sois do mundo, antes eu vos escolhi do meio do mundo, por isso o mundo vos aborrece.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 20, 'Lembrai-vos da palavra que eu vos disse: Não é o servo maior do que o senhor. Se eles me perseguirem a mim, também vos hão-de perseguir a vós; se guardaram a minha palavra, também hão-de guardar a vossa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 21, 'Mas tudo isto vos farão por causa do meu nome, porque não conhecem aquele que me enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 22, 'Se eu não tivesse vindo e não lhes tivesse falado, não teriam culpa, mas agora não têm desculpa do seu pecado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 23, 'Aquele que me aborrece, aborrece também meu Pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 24, 'Se eu não tivesse feito entre eles tais obras, quais nenhum outro fez, não teriam culpa, mas agora viram-nas, e, contudo, odeiam-nos, a mim e a meu Pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 25, 'Mas isto aconteceu para se cumprir a palavra que está escrita na sua Lei: Odiaram-me sem motivo (Ps. 34, 19 ; Ps. 68, 6).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 26, 'Quando, porém, vier o Paráclito, que eu vos enviarei do Pai, o Espirito da verdade, que procede do Pai, ele dará testemunho de mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 27, 'E vós também dareis testemunho, porque estais comigo desde o princípio.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 1, 'Eu disse-vos estas coisas, para que vos não escandalizeis. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 2, 'Lançar-vos-ão fora das sinagogas. Virá tempo, em que todo o que vos matar, julgará prestar culto a Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 3, 'Procederão deste modo, porque não conheceram nem o Pai, nem a mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 4, 'Ora eu disse-vos estas coisas para que, quando chegar esse tempo, vos lembreis de que vo-las disse. Não vos disse isto, porém, desde o princípio, porque estava convosco. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 5, 'Agora vou para aquele que me enviou, e nenhum de vós me pergunta: Para onde vais?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 6, 'Mas, porque vos disse estas coisas, a tristeza encheu o vosso coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 7, 'Todavia digo-vos a verdade: A vós convém que eu vá porque, se não for, o Defensor não virá a vós; mas, se for, eu vo-lo enviarei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 8, 'Ele, quando vier, convencerá o mundo, quanto ao pecado, à justiça e ao juízo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 9, 'Quanto ao pecado, porque não creram em mim;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 10, 'quanto à justiça, porque vou para o Pai, e vós não me vereis mais; (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 11, 'quanto ao juízo, porque o príncipe deste mundo já está julgado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 12, 'Tenho ainda muitas coisas a dizer-vos, mas não as podeis compreender agora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 13, 'Quando vier, porém, o Espírito de verdade, ele vos guiará no caminho da verdade integral, porque não falará de si mesmo, mas dirá tudo o que tiver ouvido, e anunciar-vos-á as coisas que estão para vir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 14, 'Ele me glorificará, porque receberá do que é meu e vo-lo anunciará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 15, 'Tudo o que o Pai tem, é meu. Por isso eu vos disse que ele receberá do que é meu e vo-lo anunciará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 16, 'Um pouco, e já não me vereis; outra vez um pouco, e ver-me-eis, porque vou para o Pai." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 17, 'Disseram então entre si alguns dos seus discípulos: "Que é isto que ele nos diz; Um pouco, e já me não vereis, e outra vez um pouco, e ver-me-eis? Que significa também: Porque vou para o Pai?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 18, 'Diziam pois: "Que é isto que ele diz: Um pouco? Não sabemos o que ele quer dizer."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 19, 'Jesus, conhecendo que queriam interrogá-lo, disse-lhes: "Vós perguntais uns aos outros por que é que eu disse: Um pouco, e já me não vereis, e outra vez um pouco, e ver-me-eis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 20, 'Em verdade, em verdade, vos digo, que haveis de chorar e gemer, e o mundo se há-de alegrar; haveis de estar tristes, mas a vossa tristeza há-de converter-se em alegria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 21, 'A mulher, quando dá à luz, está em sofrimento, porque chegou a sua hora, mas, depois que deu à luz um menino, já se não lembra da sua aflição, pelo gozo que sente de ter nascido um homem para o mundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 22, 'Vós, pois, também estais agora tristes, mas hei-de ver-vos de novo, e o vosso coração se alegrará, e ninguém vos tirará a vossa alegria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 23, 'Naquele dia, não me interrogareis sobre nada. Em verdade, em verdade, vos digo, que, se pedirdes a meu Pai alguma coisa em meu nome, ele vo-la dará. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 24, 'Até agora não pedistes nada em meu nome; pedi e recebereis, para que o vosso gozo seja completo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 25, 'Tenho-vos dito estas coisas em parábolas. Mas vem o tempo em que não vos falarei já por parábolas, mas abertamente vos falarei do Pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 26, 'Nesse dia pedireis, em meu nome, e não vos digo que hei-de rogar ao Pai por vós, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 27, 'porque o mesmo Pai vos ama, porque vós me amaste e crestes que saí do Pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 28, 'Saí do Pai e vim ao mundo; outra vez deixo o mundo e vou para o Pai."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 29, 'Os seus discípulos disseram-lhe: "Eis que agora falas claramente, e não usas nenhuma parábola.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 30, 'Agora conhecemos que sabes tudo, e que não é necessário que alguém te interrogue. Por isso cremos que saíste de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 31, 'Jesus respondeu-lhes: "Credes agora?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 32, 'Eis vem a hora, e já chegou, em que sereis espalhados, cada um para seu lado, e em que me deixareis só; mas eu não estou só, porque o Pai está comigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 33, 'Disse-vos estas coisas, para que tenhais paz em mim. Haveis de ter aflições no mundo; mas tende confiança, eu venci o mundo."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 1, 'Assim falou Jesus; depois, levantando os olhos ao céu, disse: "Pai, chegou a hora, glorifica o teu Filho, para que teu Filho te glorifique a ti,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 2, 'e, pelo poder que lhe deste sobre toda a criatura, dê a vida eterna a todos os que lhe deste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 3, 'Ora a vida eterna é esta: Que te conheçam a ti como o único Deus verdadeiro, e a Jesus Cristo, a quem enviaste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 4, 'Glorifiquei-te sobre a terra; acabei a obra que me deste a fazer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 5, 'E agora, Pai, glorifica-me junto de ti mesmo, com aquela glória que tinha em ti, antes que houvesse mundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 6, 'Manifestei o teu nome aos homens, que me deste do meio do mundo. Eram teus, e tu mos deste; e guardaram a tua palavra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 7, 'Agora sabem que todas as coisas que me deste, vêm de ti,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 8, 'porque lhes comuniquei as palavras que me confiaste; eles as receberam, e conheceram verdadeiramente que eu sai de ti e creram que me enviaste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 9, 'É por eles que eu rogo; não rogo pelo mundo, mas por aqueles que me deste, porque são teus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 10, 'Todas as minhas coisas são tuas, e todas as tuas coisas são minhas; e sou glorificado neles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 11, 'Já não estou no mundo, mas eles estão no mundo, e eu vou para ti. Pai Santo, guarda em teu nome aqueles que me deste, para que sejam um, assim como nós. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 12, 'Quando eu estava com eles, os guardava em teu nome. Conservei os que me deste; nenhum deles se perdeu, excepto o filho da perdição, cumprindo-se a Escritura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 13, 'Mas agora vou para ti e digo estas coisas, estando ainda no mundo, para que eles tenham em si mesmos a plenitude do meu gozo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 14, 'Dei-lhes a tua palavra, o mundo os odiou, porque não são do mundo, como também eu não sou do mundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 15, 'Não peço que os tires do mundo, mas que os guardes do mal. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 16, 'Eles não são do mundo, como também não sou do mundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 17, 'Santifica-os pela verdade. A tua palavra é a verdade. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 18, 'Assim como tu me enviaste ao mundo, também eu os enviei ao mundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 19, 'Por eles eu me consagro a mim mesmo, para que também sejam verdadeiramente santificados. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 20, 'Não rogo somente por eles, mas também por aqueles que hão-de crer em mim por meio da sua palavra,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 21, 'para que sejam todos um, como tu, Pai, o és em mim, e eu em ti, para que também eles sejam um em nós, a fim de que o mundo creia que me enviaste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 22, 'Dei-lhes a glória que me deste, para que sejam um, como também nós somos um:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 23, 'Eu neles, e tu em mim, para que a sua seriedade seja perfeita, e para que o mundo conheça que me enviaste e que os amaste, como me amaste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 24, 'Pai, quero que, onde eu estou, estejam também comigo aqueles que me deste, para que contemplem a minha glória, a glória que me deste, porque me amaste antes da criação do mundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 25, 'Pai justo, o mundo não te conheceu, mas eu conheci-te, e estes conheceram que me enviaste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 26, 'Fiz-lhes e far-lhes-ei conhecer o teu nome, a fim de que o amor com que me amaste, esteja neles, e eu neles."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 1, 'Tendo Jesus dito estas palavras, saiu com os seus discípulos para a outra banda da torrente do Cedron, onde havia um horto, no qual entrou com os seus discípulos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 2, 'Ora Judas, o traidor, conhecia bem este lugar, porque Jesus tinha ido lá muitas vezes com seus discípulos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 3, 'Tendo, pois, Judas tomado a coorte e guardas, fornecidos pelos pontífices e fariseus, foi lá com lanternas, archotes e armas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 4, 'Jesus que sabia tudo o que estava para lhe acontecer, adiantou-se e disse-lhes: "A quem buscais?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 5, 'Responderam-lhe: "A Jesus de Nazaré." Jesus disse-lhes: "Sou eu." Judas, que o entregava, estava lá com eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 6, 'Apenas, pois, Jesus lhes disse: "Sou eu", recuaram e caíram por terra. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 7, 'Perguntou-lhes, novamente: "A quem buscais?" Eles disseram: "A Jesus de Nazaré."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 8, 'Jesus respondeu: "Já vos disse que sou eu; se é, pois, a mim que buscais, deixai ir estes."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 9, 'Deste modo se cumpriu a palavra que tinha dito: "Dos que me deste, não perdi nenhum."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 10, 'Simão Pedro, que tinha uma espada, puxou dela, feriu um servo do pontífice e cortou-lhe a orelha direita, Este servo chamava-se Malco.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 11, 'Porém, Jesus, disse a Pedro: "Mete a tua espada na bainha. Não hei-de beber o cálice que o Pai me deu?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 12, 'Então a coorte, o tribuno e os guardas dos Judeus prenderam Jesus e maniataram-no.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 13, 'Primeiramente levaram-no a casa de Anás, por ser sogro de Caifás, que era o pontífice daquele ano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 14, 'Caifás era aquele que tinha dado aos Judeus este conselho: "Convém que um só homem morra pelo povo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 15, 'Simão Pedro e um outro discípulo seguiam Jesus. Este discípulo, que era conhecido do pontífice, entrou com Jesus no pátio do pontífice. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 16, 'Pedro ficou fora à porta. Saiu então o outro discípulo, que era conhecido do pontífice, falou à porteira e fez entrar Pedro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 17, 'Então a criada porteira disse a Pedro: "Não és tu também dos discípulos deste homem?" Ele respondeu: "Não sou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 18, 'Os servos e os guardas acenderam um braseiro e aqueciam-se ao lume, porque estava frio. Pedro encontrava-se também entre eles e aquecia-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 19, 'Entretanto o pontífice interrogou Jesus sobre os seus discípulos e sobre a sua doutrina.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 20, 'Jesus respondeu-lhe: "Eu falei publicamente ao mundo; ensinei sempre na sinagoga e no templo, aonde concorrem todos os Judeus; nada disse em segredo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 21, 'Por que me interrogas? Interroga aqueles que ouviram o que eu lhes disse; eles sabem o que tenho dito."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 22, 'Tendo dito isto, um dos guardas, que estavam presentes, deu uma bofetada em Jesus, dizendo: "Assim respondes ao pontífice?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 23, 'Jesus respondeu-lhe: "Se falei mal, mostra o que eu disse de mal; se falei bem, por que me feres?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 24, 'Anás enviou-o maniatado ao pontífice Caifás.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 25, 'Estava lá Simão Pedro, aquecendo-se. Disseram-lhe: "Não és tu também dos seus discípulos?" Ele negou e respondeu: "Não sou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 26, 'Disse-lhe um dos servos do pontífice, parente daquele a quem Pedro cortara a orelha: "Não te vi eu com ele no horto?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 27, 'Pedro negou outra vez, e imediatamente cantou o galo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 28, 'Levaram então Jesus da casa de Caifás ao Pretório. Era de manhã. Não entraram no Pretório para se não contaminarem, a fim de comerem a Páscoa. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 29, 'Pilatos, pois, saiu fora, para lhes falar, e disse: "Que acusação apresentais contra este homem?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 30, 'Responderam; "Se não fosse um malfeitor, não o entregaríamos nas tuas mãos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 31, 'Pilatos disse-lhes então: Tomai-o e julgai-o segundo a vossa lei." Mas os Judeus disseram-lhe: "Não nos é permitido matar ninguém."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 32, 'Para se cumprir a palavra que Jesus dissera, significando de que morte havia de morrer. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 33, 'Tornou, pois, Pilatos a entrar no Pretório, chamou Jesus e disse-lhe: "Tu és o rei dos Judeus?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 34, 'Jesus respondeu: "Tu dizes isso de ti mesmo, ou foram outros que to disseram de mim?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 35, 'Pilatos respondeu:"Porventura sou judeu? A tua nação e os pontífices é que te entregaram nas minhas mãos. Que fizeste tu?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 36, 'Jesus respondeu: "O meu reino não é deste mundo; se o meu reino fosse deste mundo, certamente os meus ministros se haviam de esforçar para que eu não fosse entregue aos Judeus; mas o meu reino não é daqui."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 37, 'Pilatos disse-lhe então: "Logo, tu és rei?" Jesus respondeu: "Tu o dizes, sou rei. Nasci, vim ao mundo para dar testemunho da verdade; todo o que está pela verdade, ouve a minha voz."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 38, 'Pilatos disse-lhe: "O que é a verdade?" Dito isto, tornou a sair, para ir ter com os Judeus, e disse-lhes: "Não encontro nele motivo algum de condenação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 39, 'Ora é costume que eu, pela Páscoa, vos solte um prisioneiro; quereis, pois, que vos solte o rei dos Judeus?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 40, 'Então gritaram todos novamente: "Não este, mas Barrabás!" Ora Barrabás era um salteador.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 1, 'Pilatos tomou então Jesus e mandou-o flagelar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 2, 'Depois os soldados, tecendo uma coroa de espinhos, puseram-lha sobre a cabeça e revestiram-no com um manto de púrpura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 3, 'Aproximavam-se dele e diziam-lhe: "Salve, rei dos Judeus" e davam-lhe bofetadas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 4, 'Saiu Pilatos ainda outra vez fora e disse-lhes: "Eis que vo-lo trago fora, para que conheçais que não encontro nele crime algum."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 5, 'Saiu, pois, Jesus, trazendo a coroa de espinhos e o manto de púrpura. Pilatos disse-lhes: "Eis aqui o homem."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 6, 'Então os príncipes dos sacerdotes e os ministros, tendo-o visto gritaram: "Crucifica-o, crucifica-o!" Pilatos disse-lhes: "Tomai-o e crucificai-o, porque eu não encontro nele motivo algum de condenação."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 7, 'Os Judeus responderam-lhe: "Nós temos uma lei, e, segundo a lei, deve morrer, porque se fez Filho de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 8, 'Pilatos, tendo ouvido estas palavras, temeu ainda mais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 9, 'Entrou novamente no Pretório e disse a Jesus: "Donde és tu?" Mas Jesus não lhe deu resposta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 10, 'Então Pilatos disse-lhe: "Não me falas? Não sabes que tenho poder para te soltar, e também para te crucificar?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 11, 'Jesus respondeu: "Tu não terias poder algum sobre mim, se te não fosse dado do alto. Por isso, o que me entregou a ti, tem maior pecado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 12, 'Desde este momento, Pilatos procurava soltá-lo. Porém os Judeus gritaram: "Se soltas este, não és amigo de César, porque todo o que se faz rei, declara-se contra César."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 13, 'Pilatos, tendo ouvido estas palavras, conduziu Jesus para fora e sentou-se no seu tribunal, no lugar chamado Lithostrotos (em hebraica Gabhatha).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 14, 'Era o dia da Preparação da Páscoa, cerca da hora sexta. Pilatos disse aos Judeus: "Eis o vosso rei!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 15, 'Mas eles gritaram: "Tira-o, tira-o, crucifica-o!" Pilatos disse-lhes: "Pois eu hei-de crucificar o vosso rei?" Os pontífices responderam: "Não temos rei, senão César."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 16, 'Então entregou-lho, para que fosse crucificado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 17, 'Tomaram pois, Jesus, o qual, levando a sua cruz, saiu para o lugar chamado do Crânio (em hebraico Gólgotha), (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 18, 'onde o crucificaram, e com ele outros dois, um de cada lado, e Jesus no meio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 19, 'Pilatos redigiu um título, que mandou colocar sobre a cruz. Estava escrito nele: Jesus Nazareno, Rei dos Judeus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 20, 'Muitos Judeus leram este título, porque se achava perto da cidade o lugar onde foi crucificado. Estava redigido em hebraico, em latim e em grego.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 21, 'Os pontífices dos Judeus diziam, porém, a Pilatos: "Não escrevas: Rei dos Judeus, mas: Este homem disse: Eu sou Rei dos Judeus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 22, 'Pilatos respondeu: "O que escrevi, escrevi."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 23, 'Os soldados, depois de terem crucificado Jesus, tomaram as suas vestes e fizeram delas quatro partes, uma para cada soldado. Tomaram também a túnica. Quanto à túnica, que não tinha costura, toda tecida de alto a baixo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 24, 'disseram uns para os outros: "Não a rasguemos, mas lancemos sortes sobre ela, para ver a quem tocará." Cumpriu-se deste modo a Escritura, que diz: Repartiram as minhas vestes entre si, e lançaram sortes sobre a minha túnica (Ps. 21, 19). Os soldados assim fizeram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 25, 'Junto à cruz de Jesus estavam sua Mãe, a irmã de sua Mãe, Maria, mulher de Cléofas, e Maria Madalena.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 26, 'Jesus, vendo sua Mãe, e, junto dela, o discípulo que amava, disse a sua Mãe: "Mulher, eis o teu filho."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 27, 'Depois disse ao discípulo: "Eis a tua Mãe." E, desta hora por diante, a levou o discípulo para sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 28, 'Em seguida, sabendo Jesus que tudo estava consumado, para se cumprir a Escritura, disse: "Tenho sede."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 29, 'Havia sido ali posto um vaso cheio de vinagre. Então, os soldados, ensopando no vinagre uma esponja e atando-a a uma cana de hissopo, chegaram-Iha à boca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 30, 'Jesus, tendo tomado o vinagre, disse: "Tudo está consumado." Depois, inclinando a cabeça, rendeu o espírito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 31, 'Os Judeus, visto que era o dia da Preparação, para que não ficassem os corpos na cruz no sábado, porque aquele dia de sábado era de grande solenidade, rogaram a Pilatos que lhes fossem quebradas as pernas, e fossem tirados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 32, 'Foram, pois, os soldados, e quebraram as pernas ao primeiro e ao outro com quem ele havia sido crucificado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 33, 'Mas, quando chegaram a Jesus, vendo que já estava morto, não lhe quebraram as pernas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 34, 'mas um dos soldados traspassou-lhe o lado com uma lança, e imediatamente saiu sangue e água. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 35, 'O que foi testemunha deste facto o atesta e o seu testemunho é digno de fé e ele sabe que diz a verdade para que também vós acrediteis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 36, 'Porque estas coisas sucederam para que se cumprisse a Escritura: Não lhe quebreis osso algum (Ex. 12, 46 ; Nm. 9, 12).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 37, 'E também diz outro lugar da Escritura: Lançarão o olhar para aquele a quem traspassaram (Zc. 12, 10).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 38, 'Depois disto, José de Arimateia, que era discípulo de Jesus, ainda que oculto por medo dos Judeus, rogou a Pilatos que lhe deixasse levar o corpo de Jesus. Pilatos permitiu-lho. Foi, pois, e tomou o corpo de Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 39, 'Nicodemos, o que tinha ido primeiramente de noite ter com Jesus, foi também, levando uma composição de quase cem libras de mirra e de aloés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 40, 'Tomaram o corpo de Jesus e envolveram-no em lençóis com aromas, segundo a maneira de sepultar usada entre os Judeus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 41, 'Ora, no lugar em que Jesus foi crucificado, havia um horto, e no horto um sepulcro novo, em que ninguém ainda tinha sido sepultado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 42, 'Por ser o dia da Preparação dos Judeus, e o sepulcro estar perto, depositaram lá Jesus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 1, 'No primeiro dia da semana, foi Maria Madalena ao sepulcro, de manhã, sendo ainda escuro, e viu a pedra tirada do sepulcro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 2, 'Correu, então, e foi ter com Simão Pedro e com o outro discípulo, a quem Jesus amava, e disse-lhes: "Levaram o Senhor do sepulcro, e não sabemos onde o puseram."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 3, 'Partiu, pois, Pedro com o outro discípulo, e foram ao sepulcro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 4, 'Corriam ambos juntos, mas o outro discípulo corria mais do que Pedro, e chegou primeiro ao sepulcro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 5, 'Tendo-se inclinado, viu os lençóis postos no chão, mas não entrou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 6, 'Chegou depois Simão Pedro, que o seguia, entrou no sepulcro e viu os lençóis postos no chão,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 7, 'e o sudário que estivera sobre a cabeça de Jesus, o qual não estava com os lençóis, mas dobrado num lugar à parte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 8, 'Então entrou também o outro discípulo, que tinha chegado primeiro ao sepulcro. Viu e creu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 9, 'Com efeito, ainda não entendiam a Escritura, segundo a qual ele devia ressuscitar dos mortos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 10, 'Depois os discípulos voltaram para sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 11, 'Entretanto Maria (Madalena) conservava-se da parte de fora do sepulcro, chorando. Enquanto chorava, inclinou-se para o sepulcro'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 12, 'e viu dois anjos vestidos de branco, sentados no lugar onde fora posto o corpo de Jesus, um à cabeceira, outro aos pés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 13, 'Eles disseram-lhe: "Mulher, porque choras?" Respondeu-lhes: "Porque levaram o meu Senhor, e não sei onde o puseram."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 14, 'Ditas estas palavras, voltou-se para trás, e viu Jesus de pé, mas não sabia que era Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 15, 'Jesus disse-lhe: "Mulher, por que choras? A quem procuras?" Ela, julgando que era o hortelão, disse-lhe: "Senhor se tu o levaste, dize-me onde o puseste; eu irei buscá-lo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 16, 'Jesus disse-lhe: "Maria!" Ela, voltando-se, disse-lhe em hebreu: Rabbouni! (que quer dizer Mestre).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 17, 'Jesus disse-lhe: "Não me retenhas, porque ainda não subi para meu Pai; mas vai a meus irmãos e dize-lhes que subo para meu Pai, e vosso Pai, para o meu Deus, e vosso Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 18, 'Foi Maria Madalena dar a nova aos discípulos: "Vi o Senhor, e ele disse-me estas coisas."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 19, 'Chegada a tarde daquele mesmo dia, que era o primeiro da semana, e estando fechadas as portas da casa onde os discípulos se achavam juntos, com medo dos Judeus, foi Jesus, pôs-se no meio deles e disse-lhes: "A paz seja convosco!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 20, 'Dito isto, mostrou-lhes as mãos e o lado. Os discípulos alegraram-se muito ao ver o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 21, 'Ele disse-lhes novamente: "A paz seja convosco. Assim como o Pai me enviou, também vos envio a vós."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 22, 'Tendo proferido estas palavras, soprou sobre eles e disse-lhes: "Recebei o Espírito Santo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 23, 'Aqueles a quem perdoardes os pecados, ser-lhes-ão perdoados; àqueles a quem os retiverdes, ser-lhes-ão retidos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 24, 'Tomé, um dos doze, chamado Dídimo, não estava com eles, quando Jesus veio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 25, 'Os outros discípulos disseram-lhe: "Nós vimos o Senhor." Mas ele respondeu-lhes: "Se não vir nas suas mãos a abertura dos cravos, se não meter o meu dedo no lugar dos cravos e não meter a minha mão no seu lado, não crerei."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 26, 'Oito dias depois, estavam os discípulos outra vez em casa, e Tomé com eles. Veio Jesus, estando as portas fechadas, pôs-se no meio deles e disse: "A paz seja convosco."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 27, 'Em seguida disse a Tomé: "Mete aqui o teu dedo, e vê as minhas mãos, aproxima também a tua mão e mete-a no meu lado; e não sejas incrédulo, mas fiel."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 28, 'Tomé respondeu-lhe: "Meu Senhor e meu Deus!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 29, 'Jesus disse-lhe: "Tu creste, Tomé, porque me viste; bem-aventurados os que crerem sem ter visto."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 30, 'Outros muitos prodígios fez ainda Jesus na presença de seus discípulos, que não foram escritos neste livro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 31, 'Estes, porém, foram escritos a fim de que acrediteis que Jesus é o Cristo, Filho de Deus, e para que, crendo, tenhais a vida em seu nome.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 1, 'Depois disto, Jesus tornou a mostrar-se aos seus discípulos, junto do mar de Tiberíades. Mostrou-se deste modo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 2, 'Estavam juntos Simão Pedro, Tomé, chamado Dídimo, Natanael, que era de Caná da Galileia, os filhos de Zebedeu e dois outros dos seus discípulos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 3, 'Simão Pedro disse-lhes: "Vou pescar." Responderam-lhe: "Também nós vamos contigo." Partiram e entraram numa barca. Naquela noite nada apanharam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 4, 'Chegada a manhã, Jesus apresentou-se na praia; os discípulos todavia não conheceram que era ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 5, 'Jesus disse-lhes: "Ó moços, tendes alguma coisa de comer?" Responderam-lhe: "Nada."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 6, 'Disse-lhes: "Lançai a rede para o lado direito da barca, e encontrareis. Lançaram a rede, e não a podiam tirar, por causa da grande quantidade de peixes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 7, 'Então aquele discípulo, a quem Jesus amava, disse a Pedro: "É o Senhor." Simão Pedro, ao ouvir dizer que era o Senhor, cingiu-Se com a túnica (porque estava nu), e lançou-se à água. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 8, 'Os outros discípulos, que não estavam distantes de terra, senão duzentos côvados foram na barca, tirando a rede cheia de peixes. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 9, 'Logo que saltaram em terra, viram umas brasas acesas, peixe em cima delas, e pão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 10, 'Jesus disse-lhes: "Trazei dos peixes que agora apanhastes."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 11, 'Simão Pedro subiu à barca e tirou a rede para terra, cheia de cento e cinqüenta e três grandes peixes. E, sendo tantos, não se rompeu a rede.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 12, 'Jesus disse-lhes: "Vinde jantar." Nenhum dos discípulos ousava perguntar-lhe: "Quem és tu?" sabendo que era o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 13, 'Jesus aproximou-se, tomou o pão e deu-lho, e igualmente do peixe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 14, 'Foi esta a terceira vez que Jesus se manifestou aos seus discípulos, depois de ter ressuscitado dos mortos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 15, 'Tendo eles jantado, disse Jesus a Simão Pedro: "Simão, filho de João, amas-me mais do que estes?" Ele disse-lhe: "Sim, Senhor, tu sabes que eu te amo." Jesus disse-lhe: "Apascenta os meus cordeiros." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 16, 'Disse-lhe outra vez; "Simão, filho de João, amas-me?" Ele disse-lhe: "Sim, Senhor, tu sabes que eu te amo." Jesus disse-lhe: "Apascenta as minhas ovelhas."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 17, 'Disse-lhe pela terceira vez: "Simão, filho de João, amas-me?" Ficou Pedro triste, porque, pela terceira vez, lhe disse: "Amas-me?" E disse-lhe: "Senhor, tu conheces tudo; sabes que eu te amo." Jesus disse-lhe: "Apascenta as minhas ovelhas."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 18, 'Em verdade, em verdade te digo: Quando tu eras mais moço, cingias-te e ias onde desejavas; mas, quando fores velho, estenderás as tuas mãos, e outro te cingirá e te levará para onde tu não queres."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 19, 'Disse isto, indicando com que gênero de morte havia Pedro de dar glória a Deus. Depois de assim ter falado, disse: "Segue-me."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 20, 'Pedro, tendo-se voltado, viu que o seguia aquele discípulo que Jesus amava, o qual na ceia estivera reclinado sobre o seu peito, e lhe perguntara: "Senhor, quem é o que te há-de entregar?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 21, 'Por isso Pedro, vendo-o, disse a Jesus: "Senhor, e deste que será?" (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 22, 'Jesus disse-lhe: "Se quero que ele fique até que eu volte, que tens tu com isso? Tu segue-me." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 23, 'Correu esta voz entre os irmãos que aquele discípulo não morreria. Todavia Jesus não disse a Pedro: "Não morrerá", mas: "Se quero que ele fique até que eu venha, que tens tu com isso?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 24, 'Este é aquele discípulo que dá testemunho destas coisas e que as escreveu, e sabemos que é verdadeiro o seu testemunho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 25, 'Muitas outras coisas fez Jesus. Se se escrevessem, uma por uma, creio que nem no mundo todo poderiam caber os livros que seria preciso escrever. (ver nota)');
